INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('9702a557-9580-5424-aa51-f22e247fa694', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 11, 11, 'እግዚአብሔር እንዴት ያውቃል በልዑልስ ዘንድ በእውኑ ዕውቀት አለ ይላሉ'),
  ('bd9f763e-b92b-52ec-a9a1-53e97eaaceaf', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 12, 12, 'እንሆ እነዚህ ኀጢአተኛዎች ይደሰታሉ ዅልጊዜም ባለጠግነታቸውን ያበዛሉ'),
  ('933f0374-d1ce-5535-a6ce-2118d5820191', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 13, 13, 'እንዲህም አልኹ፦በእውኑ ልቤን በከንቱ አጸደቅኹ እጆቼንም በንጽሕና በከንቱ አጠብኹ'),
  ('79a8ade7-e302-59b1-af5c-dc13444ff74c', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 14, 14, 'ዅልጊዜም የተገረፍኹ ኾንኹ መሰደቤም በማለዳ ነው'),
  ('b6bbdbf0-0a37-5574-a562-0523675dc737', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 15, 15, 'እንደዚህ ብዬ ብናገር ኖሮ እንሆ የልጆችኽን ትውልድ በበደልኹ ነበር'),
  ('107ab1ad-3a7a-5bc0-aaab-f737d8077bea', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 16, 16, 'ዐውቅም ዘንድ ዐሰብኹ ይህ ግን በፊቴ ችግር ነበረ'),
  ('cee97b83-6585-5be9-ac38-3fb813e1faa0', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 17, 17, 'ወደእግዚአብሔር መቅደስ እስክገባ ድረስ ፍጻሜያቸውንም እስካስተውል ድረስ'),
  ('84692e16-3c09-5673-a3f8-65662f5f3e65', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 18, 18, 'በድጥ ስፍራ አስቀመጥኻቸው ወደ ጥፋትም ጣልኻቸው'),
  ('3aff7cb3-6422-5cec-aba6-3213b84628e7', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 19, 19, 'እንዴት ለጥፋት ኾኑ! በድንገት አለቁ ስለ ኀጢአታቸውም ጠፉ'),
  ('837268ea-7de4-5ff2-afbf-8c01f46abfea', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 20, 20, 'ከሕልም እንደሚነቃ አቤቱ ስትነቃ ምልክታቸውን ታስነውራለኽ'),
  ('cbe44cfb-d7c6-572b-afea-813e21d8d86a', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 21, 21, 'ልቤ ነዷ፟ልና ኵላሊቴም ቀልጧልና'),
  ('b2aa10ed-5806-5f83-a73b-ca9adfbc6fc7', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 22, 22, 'እኔ የተናቅኹ ነኝ አላውቅኹምም ባንተ ዘንድም እንደ እንስሳ ኾንኹ'),
  ('2328b5a9-33c9-569e-a08a-1754be2a01c0', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 23, 23, 'እኔ ግን ዘወትር ከአንተ ጋራ ነኝ ቀኝ እጄንም ያዝኸኝ'),
  ('6f43daea-c748-5794-a226-7baef38b738b', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 24, 24, 'ባንተ ምክር መራኸኝ ከክብር ጋራ ተቀበልኸኝ'),
  ('3efaa8a0-9c59-5a11-ac89-f9a9e412e58b', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 25, 25, 'በሰማይ ያለኝ ምንድር ነው በምድርስ ውስጥ ከአንተ ዘንድ ምን እሻለኹ'),
  ('78a1f9b0-77e7-586b-a749-15c8827f6c34', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 26, 26, 'የልቤ አምላክ ሆይ ልቤና ሥጋዬ አለቀ እግዚአብሔር ግን ለዘለዓለም ዕድል ፈንታዬ ነው'),
  ('19894fce-011a-5f0f-a2fe-eeb55d6f2405', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 27, 27, 'እንሆ ከአንተ የሚርቁ ይጠፋሉና ከአንተ ርቀው የሚያመነዝሩትንም ዅሉ አጠፋኻቸው'),
  ('783f0ae8-a0be-5ea6-a9b4-f5fef762d1c0', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 28, 28, 'ለእኔ ግን ወደ እግዚአብሔር መቅረብ ይሻለኛል መታመኛዬም እግዚአብሔር ነው በጽዮን ልጅ በሮች ምስጋናኽን ዅሉ እናገር ዘንድ'),
  ('8a65d1d3-3d90-5049-a481-920adc519a1d', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 1, 1, 'አቤቱ ስለ ምን ለዘወትር ጣልኸኝ በማሰማሪያኽ በጎች ላይስ ቍጣኽን ስለ ምን ተቈጣኽ'),
  ('4cd52d35-3495-5cec-adef-5c440bbaeb1c', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 2, 2, 'አስቀድመኽ የፈጠርኻትን ማኅበርኽን የተቤዠኻትንም የርስትኽን በትር በርሷ ያደርኽባትን የጽዮንን ተራራ ዐስብ'),
  ('9fcf6b8a-892b-50ea-a7f8-fa540f1f3a2b', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 3, 3, 'ጠላት በቅዱሳንኽ ላይ እንደ ከፋ፟ መጠን ዅልጊዜም በትዕቢታቸው ላይ እጅኽን አንሣ'),
  ('6cea4526-c504-577a-af6c-60afc44ad6cf', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 4, 4, 'ጠላቶችኽ በበዓል መካከል ተመኩ የማያውቁትንም ምልክት ምልክታቸው አደረጉ'),
  ('704cccc1-c6dd-5326-ad03-f317378f0c24', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 5, 5, 'እንደ ላይኛው መግቢያ ውስጥ በዱር እንዳሉም ዕንጨቶች በመጥረቢያ በሮቿን ሰበሩ'),
  ('405c4211-da39-5dba-a5e7-346935534817', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 6, 6, 'እንዲሁ በመጥረቢያና በመዶሻ ሰበሯት'),
  ('98248b85-0847-5f59-a49a-5133d376ae98', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 7, 7, 'መቅደስኽን በእሳት አቃጠሉ የስምኽንም ማደሪያ በምድር ውስጥ አረከሱ'),
  ('53a30864-6805-5380-ac32-766fb9daf5a2', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 8, 8, 'አንድ ኾነው በልባቸው በየሕዝባቸው ኑ የእግዚአብሔርን በዓሎች ከምድር እንሻር አሉ'),
  ('2a63978a-eea9-5a6c-a790-5b062c45f639', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 9, 9, 'ምልክታችንን አናይም ከእንግዲህ ወዲህም ነቢይ የለም እስከ መቼ እንዲኖር የሚያውቅ በኛ ዘንድ የ ለም'),
  ('b36e4819-e00c-5ce2-addb-8c9136331b89', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 10, 10, 'አቤቱ ጠላት እስከ መቼ ይሳደባል ስምኽን ጠላት ዅልጊዜ ያቃልላልን'),
  ('83fb83d5-59e2-5d58-a163-ed35497e784f', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 11, 11, 'ቀኝኽንም በብብትኽ መካከል እጅኽንም ፈጽመኽ ለምን ትመልሳለኽ'),
  ('53a81968-f0af-5439-a86e-630385cc71d1', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 12, 12, 'እግዚአብሔር ግን ከዓለም አስቀድሞ ንጉሥ ነው በምድርም መካከል መድኀኒትን አደረገ'),
  ('8e7c082c-1e1f-5924-a578-846d173809c7', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 13, 13, 'አንተ ባሕርን በኀይልኽ አጸናኻት አንተ የእባቦችን ራስ በውሃ ውስጥ ሰበርኽ'),
  ('cf5f02a9-5326-505b-accf-a0a4f8bb82a2', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 14, 14, 'አንተም የዘንዶውን ራሶች ቀጠቀጥኽ ለኢትዮጵያ ሰዎችም ምግባቸውን ሰጠኻቸው'),
  ('9268ca73-b3ac-597f-a6c9-572ac8fabdd9', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 15, 15, 'አንተ ምንጮቹንና ፈሳሾቹን ሰነጠቅኽ አንተ ዅልጊዜ የሚፈሱ፟ትን ወንዞች አደረቅኽ'),
  ('ffd8b4ba-1e97-507e-aac0-07771fb3f9cc', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 16, 16, 'ቀኑ የአንተ ነው ሌሊቱም የአንተ ነው አንተ ፀሓዩንና ጨረቃውን አዘጋጀኽ'),
  ('d27568a2-7bee-5c06-a054-7f855e611383', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 17, 17, 'አንተ የምድርን ዳርቻ ዅሉ ሠራኽ በጋንም ክረምትንም አንተ አደረግኽ'),
  ('52198f8b-6a0f-5aec-a797-12cfba58cf0a', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 18, 18, 'ይህን ፍጥረትኽን ዐስብ ጠላት እግዚአብሔርን ተላገደ ሰነፍ ሕዝብም ስሙን አስቈጣ'),
  ('135ad90e-1a10-5f91-a922-c960b1083af0', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 19, 19, 'የምትገዛልኽን ነፍስ ለአራዊት አትስጣት የችግረኛዎችኽን ነፍስ ለዘወትር አትርሳ'),
  ('be581d6d-06b4-50a9-ae9b-af4b8940536e', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 20, 20, 'ወደ ኪዳንኽ ተመልከት የምድር የጨለማ ስፍራዎች በኃጥኣን ቤቶች ተሞልተዋልና'),
  ('6c82347a-2279-5deb-a345-2e7fa389112f', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 21, 21, 'ችግረኛ ዐፍሮ አይመለስ ችግረኛና ምስኪን ስምኽን ያመሰግናሉ'),
  ('b0bbd024-f3be-51b3-ad3e-e33b65716897', 'dd0ed32e-8ed2-5c3d-a4d4-b008ade76df2', '20058163-155f-5b3d-ae03-05e0e801c796', 22, 22, 'አቤቱ ተነሥ በቀልኽንም ተበቀል ሰነፎች ዅልጊዜም የተላገዱኽን ዐስብ'),
