  ('4f057cc5-e03e-52f6-aee7-bdd52593f23e', '9d5f7feb-a916-50bf-abb9-5ea540136999', '3507139d-f40e-5ba6-a601-e932b93082cd', 4, 4, 'አንተ በዘለዓለም ተራራዎች ኾነኽ በድንቅ ታበራለኽ'),
