  ('db0c8c10-7ef5-57b5-a108-03e46a74f73e', '9d5f7feb-a916-50bf-abb9-5ea540136999', '3507139d-f40e-5ba6-a601-e932b93082cd', 9, 9, 'ልበ የዋሃንን ያድን ዘንድ እግዚአብሔር ለፍርድ በተነሣ ጊዜ'),
