  ('5ec46dc5-8000-5fe6-a04a-260b357734fd', 'acbaba16-adad-5466-a9fb-4713454a6bde', 'c7daf63a-ff70-5392-adca-9951d4874c08', 16, 16, 'አቤቱ ውሃዎች አዩኽ ውሃዎችም አይተውኽ ፈሩ ጥልቆች ተነዋወጡ ውሃዎችም ጮኹ'),
  ('cdb40e01-a544-504d-a15a-61a9fdcc8700', 'acbaba16-adad-5466-a9fb-4713454a6bde', 'c7daf63a-ff70-5392-adca-9951d4874c08', 17, 17, 'ደመኖች ድምፅን ሰጡ ፍላጻዎችኽም ወጡ'),
  ('449d2c97-6e71-570f-aa5d-8166aabcae45', 'acbaba16-adad-5466-a9fb-4713454a6bde', 'c7daf63a-ff70-5392-adca-9951d4874c08', 18, 18, 'የነጐድጓድኽ ድምፅ በዐውሎ ነበረ መብረቆች ለዓለም አበሩ ምድር ተናወጠች ተንቀጠቀጠችም'),
  ('f720646a-343f-531a-ac6d-a57b4ca1371b', 'acbaba16-adad-5466-a9fb-4713454a6bde', 'c7daf63a-ff70-5392-adca-9951d4874c08', 19, 19, 'መንገድኽ በባሕር ውስጥ ነው ፍለጋኽም በብዙ ውሃዎች ነው አረማመድኽም አልታወቀም'),
  ('675ff704-36bf-52f0-ae75-38deefea4ac6', 'acbaba16-adad-5466-a9fb-4713454a6bde', 'c7daf63a-ff70-5392-adca-9951d4874c08', 20, 20, 'በሙሴና በአሮን እጅ ሕዝብኽን እንደ በጎች መራኻቸው'),
  ('5c96ff2e-63fb-5617-a40e-325a2fb45cfe', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 1, 1, 'ሕዝቤ ሆይ ሕጌን አድምጡ ዦሯችኹንም ወደአፌ ቃል አዘንብሉ'),
  ('1119d520-be96-5e6a-a12e-c3938862ef90', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 2, 2, 'አፌን በምሳሌ እከፍታለኹ ከቀድሞ ዠምሮ ያለውንም ተምሳሊት እናገራለኹ'),
  ('f514549b-dfb6-5a55-abf7-c289e4e99026', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 3, 3, 'የሰማነውንና ያወቅነውን አባቶቻችንም የነገሩንን ለሚመጣ ትውልድ ከልጆቻቸው አልሰወሩም'),
  ('6b9aceff-2c10-5172-a0b0-9c4b4bfbcc3b', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 4, 4, 'የእግዚአብሔርን ምስጋናና ኀይሉን ያደረገውንም ተኣምራት ተናገሩ'),
  ('2a78f7c7-720b-5858-ad53-1a5b3a19b148', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 5, 5, 'ለልጆቻቸው ያስታውቅ ዘንድ ለአባቶቻችን ያዘዘውን ምስክር በያዕቆብ አቆመ በእስራኤልም ሕግን ሠራ'),
  ('3ea914e5-ee80-561f-a8e4-290aab980c28', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 6, 6, 'የሚመጣ ትውልድ የሚወለዱም ልጆች ያውቁ ዘንድ ተነሥተው ለልጆቻቸው ይነግራሉ'),
  ('16c3e282-e30f-5b80-a19f-bdd41140a0b0', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 7, 7, 'ተስፋቸውን በእግዚአብሔር እንዲያደርጉ የእግዚአብሔርንም ሥራ እንዳይረሱ ትእዛዙንም እንዲጠብቁ'),
  ('7e244f96-66f8-580a-a7ec-953baa125b76', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 8, 8, 'እንደ አባቶቻቸው እንዳይኾኑ ጠማማና የምታስመርር ትውልድ ልቧን ያላቀናች ትውልድ ነፍሷ በእግዚአ ብሔር ዘንድ ያልታመነች'),
  ('2774c8bc-9749-5358-a931-21f2d0e4e93f', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 9, 9, 'የኤፍሬም ልጆች ለሰልፍ ታጥቀው ቀስትንም ገትረው በሰልፍ ቀን ወደ ዃላ ተመለሱ'),
  ('7ecc30a8-a53c-51a5-a648-419a29119891', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 10, 10, 'የእግዚአብሔርን ኪዳን አልጠበቁም በሕጉም ለመመላለስ እንቢ አሉ'),
  ('4598430a-8972-5fe4-a2ba-97274f4ffc5f', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 11, 11, 'መልካም ሥራውንና ያሳያቸውን ተኣምራቱን ረሱ'),
  ('de0bb930-4664-52e1-ad2f-95807fa49abc', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 12, 12, 'በግብጽ አገርና በጣኔዎስ በረሓ በአባቶቻቸው ፊት የሠራውን ተኣምራት'),
  ('6c770df2-861c-569b-ac7b-64285c82e453', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 13, 13, 'ባሕርን ከፍሎ አሳለፋቸው ውሃዎችን እንደ ክምር አቆመ'),
  ('e8176d40-cd62-56ab-a966-082adb85c6a8', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 14, 14, 'ቀን በደመና መራቸው ሌሊቱንም ዅሉ በእሳት ብርሃን'),
  ('efc296d4-a45c-54a0-a2d2-7213c71e587c', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 15, 15, 'አለቱን በምድረ በዳ ሰነጠቀ ከጥልቅ እንደሚገኝ ያኽል በብዙ አጠጣቸው'),
  ('aa284b59-ce0e-5439-aa27-4e73b95a738b', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 16, 16, 'ውሃን ከጭንጫ አወጣ ውሃንም እንደ ወንዞች አፈሰሰ'),
  ('fd7c9795-f234-57d5-a37c-9dc2790aff0e', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 17, 17, 'ነገር ግን ይበድሉት ዘንድ እንደ ገና ደገሙ ልዑልንም በምድረ በዳ አስቈጡት'),
  ('4513e2da-df21-578b-ae90-a06e74768ff4', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 18, 18, 'ለነፍሳቸው መብልን ይፈልጉ ዘንድ እግዚአብሔርን በልባቸው ፈተኑት'),
  ('25b99f3c-884f-56d1-a5f4-5f4fd8503472', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 19, 19, 'እግዚአብሔርን እንዲህ ብለው ዐሙት፦እግዚአብሔር በምድረ በዳ ማእዱን ያሰናዳ ዘንድ ይችላልን'),
  ('77fbd218-a848-5a42-a733-3f1a7086d43b', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 20, 20, 'አለቱን መታ ውሃዎችም ወጡ ወንዞችም ጐረፉ እንጀራን መስጠትስ ይችላልን ለሕዝቡስ ማእዱን ያዘጋ ጃልን'),
  ('72c8e7d6-f895-5adb-a4e3-baa967145a3c', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 21, 21, 'እግዚአብሔርም ይህን ሰምቶ ተቈጣ በያዕቆብም ላይ እሳት ነደደ መዓትም በእስራኤል ላይ መጣ'),
  ('d628cf11-92d1-5fa5-a42b-b9a540ff6d9a', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 22, 22, 'በእግዚአብሔር አላመኑምና በመድኀኒቱም አልተማመኑምና'),
  ('906ff20c-3005-52d7-aea0-e4d2e916cee6', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 23, 23, 'ደመናውንም ከላይ አዘዘ የሰማይንም ደጆች ከፈተ'),
  ('df49cc37-91f8-58f3-a276-65f268585c39', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 24, 24, 'ይበሉም ዘንድ መናን አዘነበላቸው የሰማይንም እንጀራ ሰጣቸው'),
  ('15c93ce9-f7b0-5cf1-ae86-b97bf724fcee', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 25, 25, 'የመላክትንም እንጀራ ሰው በላ ሥንቅንም እስኪተርፋቸው ላከላቸው'),
  ('dd8c5011-42d4-52e3-a3e8-04ef34035ee8', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 26, 26, 'ከሰማይ የምሥራቅን ነፋስ አስነሣ በኀይሉም የደቡብን ነፋስ አመጣ'),
  ('4198072d-f313-5541-a9d1-7f7541db1721', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 27, 27, 'ሥጋን እንደ ዐፈር የሚበሩ፟ትንም ወፎች እንደ ባሕር አሸዋ አዘነበላቸው'),
  ('eb4f7b41-ef55-553d-a4fd-fdfa365119f2', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 28, 28, 'በሰፈራቸው መካከል በድንኳናቸውም ዙሪያ ወደቀ'),
  ('688dedb6-3c75-57f1-a5cc-d04209ac0445', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 29, 29, 'በሉ እጅግም ጠገቡ ምኞታቸውንም ሰጣቸው'),
  ('5b8c7f16-9e24-560b-aaf2-6539dea1cf0a', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 30, 30, 'ከወደዱትም አላሳጣቸውም መብላቸውም ገና በአፋቸው ሳለ'),
  ('813617d5-80f2-567a-a3c1-916a5fa18e33', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 31, 31, 'የእግዚአብሔር ቍጣ በላያቸው መጣ ከነርሱም ከፍ ያሉትን ገደለ የእስራኤልንም ምርጦች አሰናከለ'),
  ('ae7a43e6-8654-5bbc-acbd-64170f522871', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 32, 32, 'ከዚህም ዅሉ ጋራ እንደ ገና በደሉ ተኣምራቱንም አላመኑም'),
  ('57b769ff-b5b9-50c6-a5a0-fb857cdcd361', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 33, 33, 'ቀኖቻቸውም በከንቱ አለቁ ዓመቶቻቸውም በችኰላ'),
  ('a31dc569-4b86-58cf-af5d-5b2a85bdfb87', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 34, 34, 'በገደላቸውም ጊዜ ወዲያው ፈለጉት ተመለሱ ወደ እግዚአብሔርም ገሠገሡ'),
  ('db327427-2d5e-560c-a2c0-90fb7a157b41', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 35, 35, 'ረዳታቸውም እግዚአብሔር መድኀኒታቸውም ልዑል አምላክ እንደ ኾነ ዐሰቡ'),
  ('95016159-abc6-5edd-ae6f-1ab21bc0daf9', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 36, 36, 'በአፋቸው ብቻ ወደዱት በአንደበታቸውም ዋሹበት'),
  ('718a304a-21a8-57a2-a241-a4468cd86ee8', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 37, 37, 'ልባቸውም ከርሱ ጋራ አልቀናም በቃል ኪዳኑም አልተማመኑትም'),
  ('1d9f4efa-eef4-501d-a82c-20fc2af78516', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 38, 38, 'ርሱ ግን መሓሪ ነው ኀጢአታቸውንም ይቅር አላቸው አላጠፋቸውምም ቍጣውንም መመለስ አበዛ መዓቱን ም ዅሉ አላቃጠለም'),
  ('cc4f3c92-2338-5afe-a4d8-19526f789877', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 39, 39, 'ወጥቶ የማይመለስ መንፈስ ሥጋም እንደ ኾኑ ዐሰበ'),
  ('7ed143dc-e444-5228-a454-9102b3e68d44', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 40, 40, 'በምድረ በዳ ምን ያኽል አስቈጡት በበረሓም አሳዘኑት'),
  ('ca52bf86-bd4b-5cb3-a78d-bbfd6ac0be16', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 41, 41, 'ተመለሱ እግዚአብሔርንም ፈተኑት የእስራኤልንም ቅዱስ አሳዘኑት'),
  ('d6d25443-e242-5ecd-ab9c-ce22ba5571c4', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 42, 42, 'እነርሱም እጁን አላሰቡም ከጠላቶቻቸው እጅ ያዳነበትን ቀን'),
  ('2aac99b2-17e8-5a50-a311-9a95ff5e0493', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 43, 43, 'በግብጽ ያደረገውን ተኣምራቱን በጣኔዎስም በረሓ ያደረገውን ድንቁን'),
  ('85a3c7fa-8e68-5d11-ae06-6dd7da51aac5', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 44, 44, 'ወንዞቻቸውንም ወደ ደም ለወጠ ምንጮቻቸውን ደግሞ እንዳይጠጡ'),
  ('ab95d265-0e17-5937-a7bc-340d906ab6c2', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 45, 45, 'ዝንቦችንም በላያቸው ሰደደባቸው በሏቸውም በጓጕንቸርም አጠፋቸው'),
  ('a269dc20-75d1-555d-a731-3d9c76250b35', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 46, 46, 'ፍሬያቸውን ለኵብኵባ ሥራቸውንም ለአንበጣ ሰጠ'),
  ('2f7c92d5-8d79-5626-acbc-d7191a3ce414', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 47, 47, 'ወይናቸውን በበረዶ በለሳቸውንም በዐመዳይ አጠፋ'),
  ('4ba84b36-087f-53bc-ac97-8051cc47af03', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 48, 48, 'እንስሳዎቻቸውን ለበረዶ ሀብታቸውንም ለእሳት ሰጠ'),
  ('0ffcd5fd-b7b5-5421-ad28-91226b94f2f1', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 49, 49, 'የመዓቱን መቅሠፍት በላያቸው ሰደደ መቅሠፍትን መዓትንም መከራንም በክፉዎች መላእክት ሰደደ'),
  ('5178b910-a981-5b90-abbe-e16baf0f2cee', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 50, 50, 'ለቍጣው መንገድን ጠረገ ነፍሳቸውንም ከሞት አላዳናትም እንስሳዎቻቸውንም በሞት ውስጥ ዘጋ'),
  ('b66ae2a5-961e-5a95-a156-45a89f8726fa', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 51, 51, 'በኵሮቻቸውን ዅሉ በግብጽ የድካማቸውንም መዠመሪያ በካም ድንኳኖች ገደለ'),
  ('e432c0df-df75-5e8e-a039-9e8cbf94c070', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 52, 52, 'ሕዝቡን ግን እንደ በጎች አሰማራቸው እንደ መንጋም በምድረ በዳ መራቸው'),
  ('2880988a-6625-5570-a213-d6d9023b0940', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 53, 53, 'በተስፋም መራቸው አልፈሩምም ጠላቶቻቸውንም ባሕር ደፈናቸው'),
  ('228e27e6-ddfb-5cf7-a747-a95120b34070', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 54, 54, 'ወደመቅደሱም ተራራ አገባቸው ቀኙ ወደ ፈጠረችው ወደዚች ተራራ'),
  ('3cca2bc9-f841-5541-ae79-bdb487480b77', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 55, 55, 'ከፊታቸውም አሕዛብን አባረረ ርስቱንም በገመድ አካፈላቸው የእስራኤልንም ወገኖች በቤታቸው አኖረ'),
  ('7e71f997-8e9c-5f1c-a570-8fabe5e6096a', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 56, 56, 'ነገር ግን ልዑል እግዚአብሔርን ፈተኑት አስቈጡትም ምስክሩንም አልጠበቁም'),
  ('aa2f1df5-ad78-5133-a621-124e4ca63ac0', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 57, 57, 'ተመለሱም እንደ አባቶቻቸውም ከዱ እንደ ጠማማ ቀስትም ተገለበጡ'),
  ('c549ff39-21c9-538c-a045-5aa1b5ee3405', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 58, 58, 'በኰረብታ መስገጃዎቻቸውም አስቈጡት በተቀረጹ ምስሎቻቸውም አስቀኑት'),
  ('f76813b0-d132-5990-af51-ab5fffa7f5c3', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 59, 59, 'እግዚአብሔርም ይህን ሰምቶ ተቈጣ እስራኤልንም እጅግ ናቀ'),
  ('272e0e30-9ba2-54cf-a0ac-86fc27939035', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 60, 60, 'የሴሎምን ማደሪያ ተዋት በሰዎች መካከል ያደረገባትን ድንኳኑን'),
  ('ce3da684-ebb2-50d2-a680-df482148edc8', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 61, 61, 'ኀይላቸውን ለምርኮ ሽልማቱንም በጠላት እጅ ሰጠ'),
  ('d6e918c0-fc9c-53f2-aa5c-b37f27cceb06', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 62, 62, 'ሕዝቡንም በጦር ውስጥ ዘጋቸው ርስቱንም ቸል አላቸው'),
  ('11cae2c4-2893-5283-a7a4-65de8ec7a4af', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 63, 63, 'ጕልማሳዎቻቸውን እሳት በላቸው ቈነዣዥቶቻቸውም አላዘኑም'),
  ('92472a5c-5882-59a0-afeb-5cb2a4b61463', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 64, 64, 'ካህናታቸውም በሰይፍ ወደቁ ባልቴቶቻቸውም አላለቀሱላቸውም'),
  ('4a4e264e-a4db-543b-a193-bc77f4a8e71d', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 65, 65, 'እግዚአብሔርም ከእንቅልፍ እንደሚነቃ ተነሣ የወይን ስካር እንደ ተወው እንደ ኀያልም ሰው'),
  ('979c61ff-549d-5ebf-a983-0353dc9618df', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 66, 66, 'ጠላቶቹንም በዃላቸው መታ የዘለዓለምን ኀሣር ሰጣቸው'),
  ('b463df1e-05b9-5386-a31d-76d0bd657100', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 67, 67, 'የዮሴፍንም ድንኳን ተዋት የኤፍሬምንም ወገን አልመረጠውም'),
  ('14f0292b-9ee6-58b6-a803-55f4b30e61e3', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 68, 68, 'የይሁዳን ወገን ግን መረጠ የወደደውን የጽዮንን ተራራ'),
  ('6c79d8d4-479c-5a85-a126-1800543d4bf6', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 69, 69, 'መቅደሱን እንደ አርያም ሠራ ለዘለዓለምም በምድር ውስጥ መሠረታት'),
  ('aea1c147-f1d0-5aec-a412-f2cab58c4bfb', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 70, 70, 'ዳዊትንም ባሪያውን መረጠው ከበጎቹም መንጋ ውስጥ ወሰደው'),
  ('155bfc5c-e2cb-5ac1-a409-9981098890d4', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 71, 71, 'ከሚያጠቡ በጎችም በዃላ ባሪያውን ያዕቆብን ርስቱንም እስራኤልን ይጠብቅ ዘንድ ወሰደው'),
  ('3dca8d67-1193-5ea4-a0ca-ea433dc34de2', '07e03306-b256-5ac2-a6d9-ca2cfaab3dac', '4bad818d-a1e9-5afa-a4b9-5834796b9562', 72, 72, 'በልቡ ቅንነት ጠበቃቸው በእጁም ብልኀት መራቸው'),
  ('2b24dbca-2db4-5dca-adb4-63eb682c4f5b', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 1, 1, 'አቤቱ አሕዛብ ወደ ርስትኽ ገቡ የቅድስናኽንም መቅደስ አረከሱ ኢየሩሳሌምንም እንደ መደብ አደረጓ ት'),
  ('bb081f7c-dd5b-5959-a00d-4f2c8b21222e', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 2, 2, 'የባሪያዎችኽንም በድኖች ለሰማይ ወፎች መብል አደረጉ የጻድቃንኽንም ሥራ ለምድር አራዊት'),
  ('f9638cec-9fe0-59d0-aa7f-fd8ba0e2a827', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 3, 3, 'ደማቸውንም በኢየሩሳሌም ዙሪያ እንደ ውሃ አፈሰሱ የሚቀብራቸውም ዐጡ'),
  ('750bc575-f9f5-5861-ac24-b0ecdbf8c045', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 4, 4, 'ለጎረቤቶቻችንም ስድብ ኾን፟ በዙሪያችንም ላሉ ሣቅና ዘበት'),
  ('fee6fa20-a48e-5aa4-a80d-fa95002fa8ed', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 5, 5, 'አቤቱ እስከ መቼ ለዘለዓለም ትቈጣለኽ ቅንአትኽም እንደ እሳት ይነዳ፟ል'),
  ('faad5658-e63d-53d0-ac15-a8ff1a79684d', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 6, 6, 'ስምኽን በማይጠሩ መንግሥታት ላይ በማያውቁኽም አሕዛብ ላይ መዓትኽን አፍስ፟'),
  ('eda6e557-0f37-552d-a9ee-5b200643c67a', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 7, 7, 'ያዕቆብን በልተውታልና ስፍራውንም ባድማ አድርገዋልና'),
  ('87790dd3-6a2e-58eb-a0e6-e8d5cbea574d', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 8, 8, 'የቀደመውን በደላችንን አታስብብን ምሕረትኽ በቶሎ ታግኘን እጅግ ተቸግረናልና'),
  ('e7a667ee-41ed-5bf5-a534-560206216d2e', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 9, 9, 'አምላካችንና መድኀኒታችን ሆይ ርዳን ስለስምኽ ክብር አቤቱ ታደገን ስለ ስምኽም ኀጢአታችንን አስ ተሰርይልን'),
  ('135ae286-ee18-5273-ab38-562ae3f03c55', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 10, 10, 'አሕዛብ አምላካቸው ወዴት ነው እንዳይሉ የፈሰሰውን የባሪያዎችኽን ደም በቀል በዐይኖቻችን ፊት አሕዛብ ያወቁ'),
  ('e65254ff-101c-5dc7-a417-a3678615d8dc', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 11, 11, 'የእስረኛዎች ጩኸት ወደ ፊትኽ ይግባ እንደ ክንድኽም ታላቅነት ሊገደሉ የተፈረደባቸውን አድን'),
  ('29028ad3-e6b4-5980-a379-760f1601e86c', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 12, 12, 'አቤቱ የተዘባበቱብኽን መዘባበታቸውን ለጎረቤቶቻችን ሰባት ዕጥፍ በብብታቸው ክፈላቸው'),
  ('8dd369a8-982b-56f8-a9a7-7de8ec5ed141', 'f4f4e98b-2188-50a3-ab94-350b3733f650', '629d47db-ed66-5e06-adae-24a7631f032b', 13, 13, 'እኛ ሕዝብኽ ግን የማሰማሪያኽም በጎች ለዘለዓለም እናመሰግንኻለን ለልጅ ልጅም ምስጋናኽን እንና ገራለን'),
  ('991460df-0504-5c0a-a8d3-c270ba89e62a', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 1, 1, 'ዮሴፍን እንደ መንጋ የምትመራ የእስራኤል ጠባቂ ሆይ አድምጥ በኪሩቤል ላይ የምትቀመጥ ተገለጥ'),
  ('3f3eca5b-958d-5109-a0c7-16a46ae6b01c', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 2, 2, 'በኤፍሬምና በብንያም በምናሴም ኀይልኽን አንሣ እኛንም ለማዳን ና'),
  ('fc27d1ba-2eaf-58d7-a613-6c4940070f2c', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 3, 3, 'አቤቱ መልሰን ፊትኽንም አብራ እኛም እንድናለን'),
  ('6c8f0ea9-aec6-545d-a567-7b0de0609583', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 4, 4, 'የሰራዊት አምላክ አቤቱ በባሪያኽ ጸሎት ላይ እስከ መቼ ትቈጣለኽ'),
  ('2473281e-c68c-55d1-a1d5-cc07bc87d769', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 5, 5, 'የእንባ እንጀራን ትመግበናለኽ እንባም በስፍር ታጠጣናለኽ'),
  ('ccc313c9-e3ce-5e17-a9d0-8d56211f5270', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 6, 6, 'ለጎረቤቶቻችን ክርክር አደረግኸን ጠላቶቻችንም በላያችን ተሣለቁብን'),
  ('448ee941-da4f-5187-a035-7c276dcef1d7', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 7, 7, 'የሰራዊት አምላክ አቤቱ መልሰን ፊትኽንም አብራ እኛም እንድናለን'),
  ('1408e275-0670-5e27-a314-cd68f388e0d3', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 8, 8, 'ከግብጽ የወይን ግንድ አመጣኽ አሕዛብን አባረርኽ ርሷንም ተከልኽ'),
  ('af1da39e-d10a-5a5c-a034-d7c726767fcb', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 9, 9, 'በፊቷም ስፍራን አዘጋጀኽ ሥሮቿንም ተከልኽ ምድርንም ሞላች'),
  ('b146987a-141c-5fb6-a280-66cdcb3b3c9f', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 10, 10, 'ጥላዋ ተራራዎችን ከደነ ጫፎቿም እንደእግዚአብሔር ዝግባ ኾኑ'),
  ('c17537ca-38d1-5681-a8f0-3c97a601d8ca', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 11, 11, 'ቅርንጫፎቿንም እስከ ባሕር ቡቃያዋንም እስከ ወንዙ ዘረጋች'),
