  ('0a09a635-a7af-5d48-a48d-f73fdb86aa96', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 14, 14, 'የሰራዊት አምላክ ሆይ እንግዲህ ተመለስ ከሰማይ ተመልከት እይም ይህችንም የወይን ግንድ ጐብኝ'),
  ('5737f8c2-2ba0-56ee-aa46-a07c019082ea', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 15, 15, 'በሰው ልጅ ለአንተ ያጸናኸውን ቀኝኽ የተከላትን አንሣ'),
  ('cd17d506-714c-5911-a1bc-34b813bd56b8', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 16, 16, 'በእሳት ተቃጥላለች ተነቅላማለች ከፊትኽ ተግሣጽም የተነሣ ይጠፋሉ'),
  ('dc165b7b-44b6-5cc3-a9eb-b8686e5c8eca', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 17, 17, 'ለአንተ ባጸናኸው በሰው ልጅ ላይ በቀኝኽ ሰው ላይ እጅኽ ትኹን'),
