  ('665f572e-0cc7-5828-a3f3-7599b7d02511', 'baa1fd58-6613-5a6d-a9f4-fc53291bea52', '73377de8-4039-5e91-a795-1194e9db78a7', 19, 19, 'የሰራዊት አምላክ አቤቱ መልሰን ፊትኽንም አብራ እኛም እንድናለን'),
  ('ede015af-ff9e-5bff-af94-7d15959d0d3c', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 1, 1, 'በረድኤታችን በእግዚአብሔር ደስ ይበላችኹ ለያዕቆብም አምላክ እልል በሉ'),
  ('04a7238c-e4e2-5e9c-a189-74e8a15d043d', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 2, 2, 'ዝማሬውን አንሡ ከበሮንም ስጡ ደስ የሚያሠኘውን በገና ከመሰንቆ ጋራ'),
  ('d7a8121e-ae61-5352-acfb-8bdde025d9a7', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 3, 3, 'በመባቻ ቀን በከፍተኛው በዓላችን ቀን መለከትን ንፉ'),
  ('083540b9-d8bb-5a62-aa8c-c28499f0b4e6', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 4, 4, 'ለእስራኤል ሥርዐቱ ነውና የያዕቆብም አምላክ ፍርድ'),
  ('4e18549c-c7f1-5c14-a07d-0f5da036a305', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 5, 5, 'ከግብጽ በወጣ ጊዜ ለዮሴፍ ምስክር አቆመው ያላወቅኹትን ቋንቋ ሰማኹ'),
  ('d0b669a9-5c02-506a-a5ef-98347898e7fe', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 6, 6, 'ጫንቃውን ከሸክም እጆቹንም በቅርጫት ከመገዛት አራቅኹ'),
  ('7ea7cf55-26d7-56b0-a27e-e6c22d2b4e57', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 7, 7, 'በመከራኽ ጊዜ ጠራኸኝ አዳንኹኽም በተሰወረ ዐውሎም መለስኹልኽ በክርክር ውሃ ዘንድም ፈተንኹኽ'),
  ('09f83956-803a-5a87-afbc-1e55a6049e9e', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 8, 8, 'ሕዝቤ ሆይ ስማኝ እነግርኻለኹም እስራኤል ሆይ እመሰክርልኻለኹ'),
  ('e1fa42cf-6378-5241-aede-7e3f92267c0c', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 9, 9, 'አንተስ ብትሰማኝ ሌላ አምላክ አይኾንልኽም ለሌላ አምላክም አትሰግድም'),
  ('e8538208-bf6e-53b1-ab9b-9be5305be71a', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 10, 10, 'ከግብጽ ምድር ያወጣኹኽ እኔ እግዚአብሔር አምላክኽ ነኝና አፍኽን አስፋ እሞላዋለኹም'),
  ('3b9d353e-2793-596b-a6ef-ab4ea09e4542', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 11, 11, 'ሕዝቤ ግን ቃሌን አልሰሙኝም እስራኤልም አላዳመጠኝም'),
  ('de7343e8-05a5-55b7-afba-04ef219338ea', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 12, 12, 'እንደ ልባቸው ሥራ ተውዃቸው በልባቸውም ዐሳብ ኼዱ'),
  ('52f5ccef-012a-561f-a6c6-baa6ba29bf04', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 13, 13, 'ሕዝቤስ ሰምቶኝ ቢኾን እስራኤልም በመንገዴ ኼደው ቢኾን'),
  ('9045807b-796b-5584-a2d7-94ab9ab675d1', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 14, 14, 'ጠላቶቻቸውን ፈጥኜ ባዋረድዃቸው ነበር በሚያስጨንቋቸውም ላይ እጄን በጣልኹ ነበር'),
  ('03287b93-95d7-54bd-a0e9-8c61de787fe4', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 15, 15, 'የእግዚአብሔር ጠላቶችም በተገዙለት ነበር ዘመናቸውም ለዘለዓለም በኾነ ነበር'),
  ('23785099-5734-5fdc-ab38-7ffcee7e2083', 'a3cab1f5-783b-54b9-acf1-6d66653a86d0', '39b6ed8a-f96a-5e8e-ab1e-693413386528', 16, 16, 'ከስንዴም ስብ ባበላቸው ነበር ከአለቱም ማር ባጠገባቸው ነበር'),
  ('8201b65e-563e-5a79-aba4-b27eadf511a6', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 1, 1, 'እግዚአብሔር በአማልክት ማኅበር ቆመ በአማልክትም መካከል ይፈርዳል'),
  ('1f1666c4-1abc-5054-a476-9b7e17b2a2ee', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 2, 2, 'እስከ መቼ ሐሰትን ትፈርዳላችኹ እስከ መቼ ለኀጢአተኛዎች ፊት ታደላላችኹ'),
  ('ebbd25e2-c2f0-5e2e-a944-ceebc5a0ebfc', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 3, 3, 'ለድኻዎችና ለድኻ አደጎች ፍረዱ ለችግረኛውና ለምስኪኑ ጽድቅ አድርጉ'),
  ('39472361-1fdb-5467-a60f-559c2dcd4a8f', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 4, 4, 'ብቸኛውንና ችግረኛውን አድኑ ከኀጢአተኛዎችም እጅ አስጥሏቸው'),
  ('295bdf76-8f12-5722-a92d-7610b59ef804', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 5, 5, 'አያውቁም አያስተውሉም በጨለማ ውስጥ ይመላለሳሉ የምድር መሠረቶች ዅሉ ተናወጡ'),
  ('4a4dca87-d40e-5f46-a647-2d722a035b23', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 6, 6, 'እኔ ግን፦አማልክት ናችኹ ዅላችኹም የልዑል ልጆች ናችኹ'),
  ('3461354e-bc73-5bdc-a573-7cd8003c1010', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 7, 7, 'ነገር ግን እንደ ሰው ትሞታላችኹ ከአለቃዎችም እንደ አንዱ ትወድቃላችኹ አልኹ'),
  ('d84061fb-6746-5508-aab0-d16dec0ec73f', '9cd97683-e79e-5c66-a0f4-442fe4ed2748', 'ddf50c02-6be0-58d0-a1d0-96f1409d0b5f', 8, 8, 'አቤቱ ተነሥ በምድር ላይ ፍርድ አንተ አሕዛብን ዅሉ ትወርሳለኽና'),
  ('4d9688af-3ca2-5c78-a352-30c34ebf75eb', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 1, 1, 'አቤቱ እንደ አንተ ማን ነው አቤቱ ዝም አትበል ቸልም አትበል'),
  ('ba7d9e55-8067-5480-a62e-42e08a6108c4', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 2, 2, 'እንሆ ጠላቶችኽ ጮኽዋልና የሚጠሉኽም ራሳቸውን አንሥተዋልና'),
  ('0f38294d-85af-5ea1-ab09-2cdba1f345e4', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 3, 3, 'ሕዝብኽን በምክር ሸነገሏቸው በቅዱሳንኽም ላይ ተማከሩ'),
  ('04454565-4b85-589d-a69d-bbd2d4250d6b', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 4, 4, 'ኑ ከሕዝብ እናጥፋቸው ደግሞም የእስራኤል ስም አይታሰብ አሉ'),
  ('c2415608-945a-51d8-ac00-bf79f78385b1', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 5, 5, 'አንድ ኾነው ባንተ ላይ ተማከሩ ባንተ ላይ ቃል ኪዳን አደረጉ'),
  ('0b977b3a-2dd9-5c0a-a3e6-b5a4ac232f87', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 6, 6, 'የኤዶማውያን ድንኳኖች እስማኤላውያንም ሞዐብም አጋራውያንም'),
  ('afea2337-8971-5c71-ab68-ccb27d4b3049', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 7, 7, 'ጌባል ዐሞንም ዐማሌቅም ፍልስጥኤማውያንም ከጢሮስ ሰዎች ጋራ'),
  ('84d7c25f-fb49-53fe-a05e-a768bfa5787e', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 8, 8, 'አሶርም ከነርሱ ጋራ ተባበረ ለሎጥ ልጆችም ረዳት ኾኗቸው'),
  ('205778d6-b740-50ff-a2ed-f571c1b60078', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 9, 9, 'እንደ ምድያምና እንደ ሢሣራ በቂሶንም ወንዝ እንደ ኢያቢስ አድርግባቸው'),
  ('39361aed-205d-5518-a01f-01ae3e3b2d8d', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 10, 10, 'በዐይንዶር ጠፉ እንደምድርም ጕድፍ ኾኑ'),
  ('950f87f6-d456-5ac8-a68f-5a99dbd356f6', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 11, 11, 'አለቃዎቻቸውን እንደ ሔሬብና እንደ ዜብ ታላላቆቻቸውንም እንደ ዛብሄልና እንደ ስልማና አድርጋቸ ው'),
  ('ccf1d1a1-114f-5515-a572-0d4ec5c72020', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 12, 12, 'የእግዚአብሔርን መሠዊያ እንወርሳለን የሚሉትን'),
  ('3a219e0b-aa0f-5133-a847-b3e15bc493f8', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 13, 13, 'አምላኬ ሆይ እንደ ትቢያ በነፋስ ፊትም እንደ ገለባ አድርጋቸው'),
  ('1f4d2514-5285-5b19-adf4-00e4ea1c95cb', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 14, 14, 'እሳት ዱርን እንደሚያቃጥል ነበልባልም ተራራዎች እንደሚያነድ፟'),
  ('edf00e1b-31ec-5b28-a2be-e6daa9a61058', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 15, 15, 'እንዲሁ በቍጣኽ አሳዳ፟ቸው በመቅሠፍትኽም አስደንግጣቸው'),
  ('7b056199-8f1c-5b2a-a2e5-90f1824696c3', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 16, 16, 'ፊታቸውን ዕፍረት ሙላው አቤቱ ስምኽንም ይፈልጋሉ'),
  ('fdfa8155-3802-50ad-ae0a-89b08f28214d', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 17, 17, 'ይፈሩ ለዘለዓለሙም ይታወኩ ይጐስቍሉ ይጥፉም'),
  ('aaaffe1b-f93d-5f1b-ab0d-892e9333e910', '3b2fc7d5-b690-5c1f-ab8b-2139fb7716ba', '0e59cd4e-5004-5bc2-afd8-5cf374569aa3', 18, 18, 'ስምኽም እግዚአብሔር እንደ ኾነ በምድር ዅሉ ላይም አንተ ብቻ ልዑል እንደ ኾንኽ ይወቁ'),
  ('e6f8ef72-be40-5740-a4c7-c2353e9abed3', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 1, 1, 'የሰራዊት አምላክ ሆይ ማደሪያዎችኽ እንደምን የተወደዱ ናቸው!'),
  ('c155034c-fd3d-5b5a-a882-db36179f8b8f', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 2, 2, 'ነፍሴ የእግዚአብሔርን አደባባዮች ትወዳ፟ለች ትናፍቅማለች ልቤም ሥጋዬም በሕያው አምላክ ደስ ተሠ ኘ'),
  ('d6515039-78a3-51ed-a018-9b1718783cc5', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 3, 3, 'ወፍ ለርሷ ቤትን አገኘች ዋኖስም ጫጩቶቿን የምታኖርበት ቤት አገኘች የሰራዊት አምላክ ንጉሤም አ ምላኬም ሆይ ርሱ መሠዊያኽ ነው'),
  ('5f6d96df-1fa0-5c73-a1ca-393dab822e80', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 4, 4, 'በቤትኽ የሚኖሩ ዅሉ የተመሰገኑ ናቸው ለዓለምና ለዘለዓለምም ያመሰግኑኻል'),
  ('793418c0-10f4-5835-ab9e-2f0b7d7cef1d', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 5, 5, 'አቤቱ ርዳታው ከአንተ ዘንድ የኾነለት በልቡም የላይኛውን መንገድ የሚያስብ ሰው ምስጉን ነው'),
  ('4b3c8e95-162b-5582-ac3b-7f903cd22e19', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 6, 6, 'በልቅሶ ሸለቆ ውስጥ በወሰነው ስፍራ የሕግ መምህር በረከትን ይሰጣልና'),
  ('5af79701-ef7d-54e6-acd8-8f46cc504579', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 7, 7, 'ከኀይል ወደ ኀይል ይኼዳሉ የአማልክት አምላክ በጽዮን ይታያል'),
  ('3663342e-6b4f-5755-aa3e-6bd6fe16d76d', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 8, 8, 'የሰራዊት አምላክ አቤቱ ጸሎቴን ስማ የያዕቆብ አምላክ ሆይ አድምጥ'),
  ('0b3959f3-d0a0-5339-a1dc-cfee1cf34f6c', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 9, 9, 'አቤቱ መታመናችንን እይልን ወደ ቀባኸውም ፊት ተመልከት'),
  ('33dbb5e5-0e98-5567-a084-3e2a73ac9d1a', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 10, 10, 'ከአእላፍ ይልቅ በአደባባዮችኽ አንዲት ቀን ትሻላለች በኃጥኣን ድንኳኖች ከመቀመጥ ይልቅ በእግዚ አብሔር ቤት እጣል ዘንድ መረጥኹ'),
  ('5c06cbb3-dfae-535d-ae6f-6e40e329d6a0', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 11, 11, 'እግዚአብሔር አምላክ ምሕረትንና እውነትን ስለ ወደደ ሞገስንና ክብርን ይሰጣል እግዚአብሔር በቅ ንነት የሚኼዱትን ከመልካም ነገር አያሳጣቸውም'),
  ('8d272501-751a-5663-aa84-01d873513e98', 'b523f391-4bc2-51e5-ae8f-83b0a60fd7ac', '08e990fe-e5ce-51da-a94f-8dfb8a7a59e2', 12, 12, 'የሰራዊት አምላክ ሆይ ባንተ የታመነ ሰው ምስጉን ነው'),
  ('10142102-3573-5d01-a27e-c3e79412a33c', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 1, 1, 'አቤቱ ለምድርኽ ሞገስን አደረግኽ የያዕቆብንም ምርኮ መለስኽ'),
  ('f0c1a370-3f16-541b-a02c-574ef48bddbc', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 2, 2, 'የሕዝብኽን ኀጢአት አስቀረኽ አበሳቸውንም ዅሉ ከደንኽ'),
  ('74561dd5-25ce-5624-ae56-c9684dc54235', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 3, 3, 'መዓትኽንም ዅሉ አስወገድኽ ከቍጣኽ መቅሠፍት ተመለስኽ'),
  ('763b9b2a-7a06-5dd7-a2c7-8111e4b239dc', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 4, 4, 'የመድኀኒታችን አምላክ ሆይ መልሰን ቍጣኽንም ከእኛ መልስ'),
  ('179b29e9-61ca-5a66-aa19-df9c92efc24e', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 5, 5, 'በእውኑ ለዘለዓለም ትቈጣናለኽን ቍጣኽንስ ለልጅ ልጅ ታስረዝማለኽን'),
  ('734ea03b-736f-5672-a7e2-127fe3e446af', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 6, 6, 'አቤቱ ትመለሳለኽ ታድነንማለኽ ሕዝቡም ባንተ ደስ ይላቸዋል'),
  ('34df7fb6-2245-539a-afaf-a37ae09a692d', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 7, 7, 'አቤቱ ምሕረትኽን አሳየን አቤቱ መድኀኒትኽንም ስጠን'),
  ('4f1a3655-f03a-5fe1-a9a9-33ffbb96ae24', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 8, 8, 'እግዚአብሔር አምላክ የሚናገረውን እሰማለኹ ሰላምን ለሕዝቡና ለቅዱሳኑ ልባቸውንም ወደ ርሱ ለሚመ ልሱ ይናገራልና'),
  ('84329ab6-1cbd-5783-a40d-a03d5092ae30', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 9, 9, 'ነገር ግን ክብር በምድራችን ያድር ዘንድ ማዳኑ ለሚፈሩት ቅርብ ነው')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('068c162e-2ecc-5624-af69-4a006a4886ca', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 10, 10, 'ምሕረትና እውነት ተገናኙ ጽድቅና ሰላም ተስማሙ'),
  ('57e33723-17d1-5ca4-ad83-bf18d11e5ede', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 11, 11, 'እውነት ከምድር በቀለች ጽድቅም ከሰማይ ተመለከተች'),
  ('fc470a7f-e303-540f-a9fe-9ea992a89462', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 12, 12, 'እግዚአብሔርም በጎ ነገርን ይሰጣል ምድራችንም ፍሬዋን ትሰጣለች'),
  ('928f68d4-e249-587d-a263-764b68d23a3d', '0bce97d7-485c-581d-a441-32b3b4bdcecc', '3452ca33-34dc-535c-a670-83b8d6c6b71d', 13, 13, 'ጽድቅ በፊቱ ይኼዳል ፍለጋውንም በመንገድ ውስጥ ያኖራል'),
  ('6aca2547-d137-5e08-a733-acdc956d059f', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 1, 1, 'አቤቱ ዦሮኽን ወደ እኔ አዘንብል አድምጠኝም ችግረኛና ምስኪን ነኝና'),
  ('151c7081-c836-5859-a960-f6c362dd94d9', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 2, 2, 'ቅዱስ ነኝና ነፍሴን ጠብቅ አምላኬ ሆይ አንተን የታመነውን ባሪያኽን አድነው'),
  ('6b56d11a-8aef-5957-afbf-dacd72b61536', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 3, 3, 'አቤቱ ቀኑን ዅሉ ወዳንተ እጮኻለኹና ማረኝ'),
  ('e84f2066-9c97-599e-a07b-c3a9e9503a48', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 4, 4, 'የባሪያኽን ነፍስ ደስ አሠኛት አቤቱ ነፍሴን ወዳንተ አነሣለኹና'),
  ('b5005076-224b-55e8-ab45-5a8d8879365e', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 5, 5, 'አቤቱ አንተ መሓሪና ይቅር ባይ ነኽና ምሕረትኽም ለሚጠሩኽ ዅሉ ብዙ ነውና'),
  ('f1177bec-84f6-585c-a537-a6baa287e104', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 6, 6, 'አቤቱ ጸሎቴን አድምጥ የልመናዬንም ድምፅ ስማ'),
  ('27061d96-c013-503d-ac6f-df119d51fd92', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 7, 7, 'ትመልስልኛለኽና በመከራዬ ቀን ወዳንተ እጠራለኹ'),
  ('296eefb2-5ee2-5e28-abdf-7dbb2340e45e', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 8, 8, 'አቤቱ ከአማልክት የሚመስልኽ የለም እንደ ሥራኽም ያለ የለም'),
  ('6fd070dc-ed42-5140-ae3e-b1b117d815fa', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 9, 9, 'ያደረግኻቸው አሕዛብ ዅሉ ይመጣሉ አቤቱ በፊትኽም ይሰግዳሉ ስምኽንም ያከብራሉ'),
  ('9cdc6bd5-58b1-552f-a4fc-36895180f3b9', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 10, 10, 'አቤቱ ድንቅ የምታደርግ አንተ ታላቅ ነኽና አንተም ብቻኽን ታላቅ አምላክ ነኽና'),
  ('014045ed-2491-500b-a750-643f3f61eec7', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 11, 11, 'አቤቱ መንገድኽን ምራኝ በእውነትኽም እኼዳለኹ ስምኽን ለመፍራት ልቤ ደስ ይለዋል'),
  ('ac22140e-3a44-5f32-a43a-b23eb85c1ece', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 12, 12, 'አቤቱ አምላኬ ሆይ በልቤ ዅሉ አመሰግንኻለኹ ለዘለዓለምም ስምኽን አከብራለኹ'),
  ('c8faa5d5-71bc-52c7-a89d-638722dcf5fe', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 13, 13, 'ምሕረትኽ በእኔ ላይ ታላቅ ናትና ነፍሴንም ከታችኛዪቱ ሲኦል አድነኻታልና'),
  ('ae70afd8-a602-582a-a1cf-efc1cb54bdc6', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 14, 14, 'አቤቱ ዐመፀኛዎች በእኔ ላይ ተነሥተዋል የክፉዎችንም ማኅበር ነፍሴን ፈለጓት በፊታቸውም አላደረ ጉኽም'),
  ('6fa996ee-b177-521f-a8dc-bcf5e0ea51f2', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 15, 15, 'አቤቱ አንተ ግን መሓሪና ርኅሩኅ አምላክ ነኽ መዓትኽ የራቀ ምሕረትኽም እውነትኽም የበዛ'),
  ('b67f13d1-8ec1-543a-a0d1-c2f5d2393ce9', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 16, 16, 'ወደ እኔ ተመልከት ማረኝም ለባሪያኽ ኀይልኽን ስጥ የሴት ባሪያኽንም ልጅ አድን'),
  ('7b7e13e8-4122-5813-aed5-0a4fd1bad49a', 'efd5a9aa-2193-5bb0-ac79-fa10bad5b66f', '597daee2-80f2-512b-a13f-d25d70c5c6a3', 17, 17, 'ምልክትንም ለመልካም ከእኔ ጋራ አድርግ የሚጠሉኝ ይዩ ይፈሩም አቤቱ አንተ ረድተኸኛልና አጽንተ ኸኛልምና'),
  ('3ed16161-c3cc-5237-a1b5-cc52e0c3b97b', '5e9781f0-06b0-58f4-a856-17e9cb4b4372', 'eadf861b-caa7-5b1f-ab18-471daff4cf9d', 1, 1, 'መሠረቶቹ በተቀደሱ ተራራዎች ናቸው'),
  ('e4acf84e-d7b8-5d29-af38-8690e97e9b39', '5e9781f0-06b0-58f4-a856-17e9cb4b4372', 'eadf861b-caa7-5b1f-ab18-471daff4cf9d', 2, 2, 'ከያዕቆብ ድንኳኖች ይልቅ እግዚአብሔር የጽዮንን ደጆች ይወዳ፟ቸዋል'),
