  ('b5afbe59-8998-5eca-a9aa-6d24441cf136', '598b854e-c096-5ec2-a4f4-c56a9fad9164', 'a9cd6396-27b4-5454-a956-e2e10692c489', 9, 9, 'የባሕርን ኀይል አንተ ትገዛለኽ የሞገዱንም መናወጥ አንተ ዝም ታሠኘዋለኽ'),
  ('909d299d-4a77-5764-a7b0-4ab42014e476', '598b854e-c096-5ec2-a4f4-c56a9fad9164', 'a9cd6396-27b4-5454-a956-e2e10692c489', 10, 10, 'አንተ ረዓብን እንደ ተገደለ አዋረድኸው በኀይልኽም ክንድ ጠላቶችኽን በተንኻቸው'),
