  ('ad9784fa-177c-511f-a9b8-b160a1429e9f', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 4, 4, 'ሺሕ ዓመት በፊትኽ እንዳለፈች እንደ ትናንት ቀን እንደ ሌሊትም ትጋት ነውና'),
