  ('6392e670-1636-5f9e-ad1f-f07f31483d72', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 6, 6, 'ማልዶ ያብባል ያልፋልም በሠርክም ጠውልጎና ደርቆ ይወድቃል'),
  ('e2ab1990-a997-5e8b-a3ec-c76b0bdf82d6', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 7, 7, 'እኛ በቍጣኽ አልቀናልና በመዓትኽም ደንግጠናልና'),
  ('a5efe55a-e4ca-5eec-ad17-51411ae21730', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 8, 8, 'የተሰወረውን ኀጢአታችንን በፊትኽ ብርሃን በደላችንንም በፊትኽ አስቀመጥኽ'),
  ('8fa85e5e-8d05-523f-ad99-433fe5ff5d68', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 9, 9, 'ዘመናችን ዅሉ ዐልፏልና እኛም በመዓትኽ አልቀናልና ዘመኖቻችንም እንደ ሸረሪት ድር ይኾናሉ'),
  ('06951dda-838b-5e86-a2de-9a65d4a5d498', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 10, 10, 'የዘመኖቻችንም ዕድሜ ሰባ ዓመት ቢበረታም ሰማንያ ዓመት ነው ቢበዛ ግን ድካምና መከራ ነው ከእ ኛ ቶሎ ያልፋልና እኛም እንገሠጻለንና'),
  ('c129f092-938f-5a6e-a532-701aa4c49609', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 11, 11, 'የቍጣኽን ጽናት ማን ያውቃል ከቍጣኽ ግርማ የተነሣ አለቁ'),
  ('f8ee12bd-a1ad-5195-a7de-721e224a5c69', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 12, 12, 'በልብ ጥበብን እንድንማር ቀኝኽን እንዲህ አስታውቀን'),
