  ('ec7256cf-a148-574d-aa6b-5517633cea99', 'a28c67f1-b709-557d-a62e-384c9bbcb577', 'c4715dd7-47b0-5e04-aa66-dab931e69212', 16, 16, 'ባሪያዎችኽንና ሥራኽን እይ ልጆቻቸውንም ምራ'),
