  ('d53f5929-6c5e-5d6f-a9e7-23f64a4d6515', '190daf0d-f507-5f85-a725-76cdf1e77ab4', 'b45695b4-65ce-572c-ad42-9877817bbbd2', 1, 1, 'በልዑል መጠጊያ የሚኖር ዅሉን በሚችል አምላክ ጥላ ውስጥ ያድራል'),
