  ('2a31605f-22a8-5fc7-a2b9-5537104c726f', '190daf0d-f507-5f85-a725-76cdf1e77ab4', 'b45695b4-65ce-572c-ad42-9877817bbbd2', 4, 4, 'በላባዎቹ ይጋርድኻል በክንፎቹም በታች ትተማመናለኽ እውነት እንደ ጋሻ ይከብ፟ኻል'),
  ('883c445e-cc32-5ea2-aef4-6a8472edb941', '190daf0d-f507-5f85-a725-76cdf1e77ab4', 'b45695b4-65ce-572c-ad42-9877817bbbd2', 5, 5, 'ከሌሊት ግርማ በቀን ከሚበር፟ ፍላጻ'),
  ('1d184794-ba66-53ea-ad04-9dd4007d9230', '190daf0d-f507-5f85-a725-76cdf1e77ab4', 'b45695b4-65ce-572c-ad42-9877817bbbd2', 6, 6, 'በጨለማ ከሚኼድ ክፉ ነገር ከአደጋና ከቀትር ጋኔን አትፈራም'),
