  ('bd702e5a-a49d-59f4-af65-ed883d347563', '190daf0d-f507-5f85-a725-76cdf1e77ab4', 'b45695b4-65ce-572c-ad42-9877817bbbd2', 15, 15, 'ይጠራኛል እመልስለትማለኹ በመከራውም ጊዜ ከርሱ ጋራ እኾናለኹ አድነዋለኹ አከብረውማለኹ'),
  ('eb1a6f58-ab02-5f47-af46-e2e3f69a44d1', '190daf0d-f507-5f85-a725-76cdf1e77ab4', 'b45695b4-65ce-572c-ad42-9877817bbbd2', 16, 16, 'ረዥምን ዕድሜ አጠግበዋለኹ ማዳኔንም አሳየዋለኹ'),
