  ('dc519d1d-0271-5a32-a327-d9e66e314b22', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 5, 5, 'አቤቱ ሥራኽ እጅግ ትልቅ ነው ዐሳብኽም እጅግ ጥልቅ ነው'),
  ('824eb760-8031-5e89-a480-3e4bbeab0618', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 6, 6, 'ሰነፍ ሰው አያውቅም ልብ የሌለውም ይህን አያስተውለውም'),
  ('dc147880-1e63-512c-a114-8a6f36b637f0', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 7, 7, 'ኀጢአተኛዎች እንደ ሣር ሲበቅሉ ዐመፃ የሚያደርጉ ዅሉ ሲለመልሙ ለዘለዓለም ዓለም እንዲጠፋ ነው'),
  ('6f601fc7-1fbe-5401-add2-6a46b9403e19', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 8, 8, 'አቤቱ አንተ ግን ለዘለዓለም ልዑል ነኽ'),
  ('7a6e83c2-64f5-5545-a2cb-f4155c1d92df', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 9, 9, 'አቤቱ እንሆ ጠላቶችኽ ይጠፋሉና ዐመፃንም የሚሠሩ ዅሉ ይበተናሉና'),
  ('b2891bd4-d18a-5f23-af27-fe26d5884a5f', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 10, 10, 'ቀንዴ አንድ ቀንድ እንዳለው ከፍ ከፍ ይላል ሽምግልናዬም በዘይት ይለመልማል'),
  ('6751c9a0-85ee-5e6e-ab75-918314bdf5cf', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 11, 11, 'ዐይኔም በጠላቶቼ ላይ አየች ዦሮዬም በእኔ ላይ በቆሙ በክፉዎች ላይ ሰማች'),
  ('b88992cd-f244-505e-ad0f-6738b6c74517', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 12, 12, 'ጻድቅ እንደ ዘንባባ ያፈራል እንደ ሊባኖስ ዝግባም ያድጋል'),
  ('cd912e57-6e3a-5131-ac02-9a27d56fd7bf', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 13, 13, 'በእግዚአብሔር ቤት ውስጥ ተተክለዋል በአምላካችንም አደባባይ ውስጥ ይበቅላሉ'),
  ('a31af2b2-40ac-5382-a3d3-4e2e55a1684b', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 14, 14, 'ያን ጊዜ በለመለመ ሽምግልና ያፈራሉ ደስተኛዎችም ኾነው ይኖራሉ'),
  ('d2904d69-ce22-55f8-a7a0-758406df6644', '6ce84d80-d178-5c43-ac6a-1fff5229fe0c', '6fba35bb-e90f-51ca-a9f4-9f8409c63763', 15, 15, 'አምላኬ እግዚአብሔር እውነተኛ እንደ ኾነ ይነግራሉ በርሱም ዘንድ ዐመፃ የለም'),
  ('997ec469-e877-58d0-ac36-b16229c1a61c', '2d003c89-875c-52cd-a6be-709c41450394', 'a8b40a57-83a1-5b3c-adff-007ab4badeb5', 1, 1, 'እግዚአብሔር ነገሠ ክብርንም ለበሰ እግዚአብሔር ኀይልን ለበሰ ታጠቀም ዓለምን እንዳትናወጥ አጸና ት'),
  ('a25dd8f9-c3c4-5c66-ab4b-d24be6d17461', '2d003c89-875c-52cd-a6be-709c41450394', 'a8b40a57-83a1-5b3c-adff-007ab4badeb5', 2, 2, 'ዙፋንኽ ከጥንት ዠምሮ የተዘጋጀ ነው አንተም ከዘለዓለም ነኽ'),
  ('b06fa1eb-ccd7-548d-a60c-14e5291a66bf', '2d003c89-875c-52cd-a6be-709c41450394', 'a8b40a57-83a1-5b3c-adff-007ab4badeb5', 3, 3, 'አቤቱ ወንዞች ከፍ ከፍ አደረጉ ወንዞች ቃሎቻቸውን ከፍ ከፍ አደረጉ'),
  ('527f310d-a123-58f0-a976-f8d54d579048', '2d003c89-875c-52cd-a6be-709c41450394', 'a8b40a57-83a1-5b3c-adff-007ab4badeb5', 4, 4, 'ከብዙ ውሃዎች ድምፅ ከባሕርም ታላቅ ሞገድ ይልቅ እግዚአብሔር በከፍታው ድንቅ ነው'),
  ('9b2b7fd0-845c-5d58-ab7f-299a6a65a372', '2d003c89-875c-52cd-a6be-709c41450394', 'a8b40a57-83a1-5b3c-adff-007ab4badeb5', 5, 5, 'ምስክርኽ እጅግ የታመነ ነው አቤቱ እስከ ረዥም ዘመን ድረስ ለቤትኽ ቅድስና ይገ፟ባ፟ል'),
  ('b84fb41b-1038-559b-a4f4-bd5968d98cee', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 1, 1, 'እግዚአብሔር የበቀል አምላክ ነው የበቀል አምላክ ተገለጠ'),
  ('7d07d53a-4f43-5b7e-a170-455a39da7c6d', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 2, 2, 'የምድር ፈራጅ ሆይ ከፍ ከፍ በል ለትዕቢተኛዎች ፍዳቸውን ክፈላቸው'),
  ('ff930d0d-a77b-5790-a6a3-aff0f32f9422', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 3, 3, 'አቤቱ ኀጢአተኛዎች እስከ መቼ ኀጢአተኛዎች እስከ መቼ ይጓደዳሉ'),
  ('3156a26f-77cd-5e77-adc0-e0979c3c8bf3', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 4, 4, 'ይከራከራሉ ዐመፃንም ይናገራሉ ዐመፃንም የሚያደርጉ ዅሉ ይናገራሉ'),
  ('b497a98f-3d59-5017-a10e-b3333ff52597', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 5, 5, 'አቤቱ ሕዝብን አዋረዱ ርስትኽንም አስቸገሩ'),
  ('21af950e-c6f1-5e48-ade6-abae6921e9dc', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 6, 6, 'ባልቴቲቱንና ድኻ አደጉን ገደሉ ስደተኛውንም ገደሉ'),
  ('96f61538-da53-57af-a14c-83ca0515556b', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 7, 7, 'እግዚአብሔር አያይም የያዕቆብ አምላክ አያስተውልም አሉ'),
  ('ad3c4c4a-6777-50be-a8b2-afd5e6919bc3', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 8, 8, 'የሕዝብ ደንቈሮዎች ሆይ አስተውሉ ሰነፎችማ መቼ ይጠበባሉ'),
  ('3a73709b-e6b9-5ee2-a519-622e26231fbe', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 9, 9, 'ዦሮን የተከለው አይሰማምን ዐይንን የሠራው አያይምን'),
  ('a17f5291-5819-57d6-a5ef-6fd41177283f', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 10, 10, 'አሕዛብንስ የሚገሥጸው ለሰውም ዕውቀት የሚያስተምረው ርሱ አይዘልፍምን'),
  ('f3fd267a-eb23-5793-a3b4-12a0718f07be', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 11, 11, 'የሰዎች ዐሳብ ከንቱ እንደ ኾነ እግዚአብሔር ያውቃል 12-13 ለኀጢአተኛ ጕድጓድ እስኪቈፈር ድረስ ከክፉዎች ዘመናት ይወገድ ዘንድ አቤቱ አንተ የገሠጽኸው ሕግኽንም ያስተማርኸው ሰው ምስጉን ነው'),
  ('519b7dd8-87c1-50b4-a879-77c2ecab5eec', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 12, 14, 'እግዚአብሔር ሕዝቡን አይጥልምና ርስቱንም አይተውምና'),
  ('e7f92c7a-7324-58fd-ab58-0e8600af8c2c', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 13, 15, 'ፍርድ ወደ ጽድቅ እስኪመልስ ድረስ ልበ ቅኖችም ዅሉ ይከተሏታል'),
  ('83305495-72dd-5def-a67b-d669bb8d43c9', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 14, 16, 'በክፉዎች ላይ ለእኔ የሚቆም ማን ነው ዐመፃንስ በሚያደርጉ ላይ ለእኔ የሚከራከር ማን ነው'),
  ('3a5c8f1f-51d4-58de-ad91-3b7c6318c565', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 15, 17, 'እግዚአብሔር የረዳኝ ባይኾን ነፍሴ ለጥቂት ጊዜ በሲኦል ባደረች ነበር'),
  ('ebe06b9d-a573-56b3-a061-1725d74f5850', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 16, 18, 'እግሮቼ ተሰናከሉ ባልኹ ጊዜ አቤቱ ምሕረትኽ ረዳኝ'),
  ('9b9cf2d7-d83e-5ae2-a153-a6486158d30b', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 17, 19, 'አቤቱ ለልቤ እንደ መከራዋ ብዛት ማጽናናትኽ ነፍሴን ደስ አሠኛት'),
  ('92e07012-2893-543a-a7c7-de9c959c3e91', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 18, 20, 'በሕግ ላይ ዐመፅን የሚሠራ የዐመፅ ዙፋን ከአንተ ጋራ አንድ ይኾናልን'),
  ('0832fb73-c7bf-591e-af77-150f057ea464', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 19, 21, 'የጻድቅን ነፍስ ያደቡባታል በንጹሕ ደምም ይፈርዳሉ'),
  ('311ea89e-19ae-50e6-af3e-d588dd0428a3', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 20, 22, 'እግዚአብሔር መጠጊያ ኾነኝ አምላኬ የተስፋዬም ረዳት ነው'),
  ('0b45dc4c-7910-54d8-af1b-64ec6e93b934', 'bfc4e213-c3c6-5cdd-a230-5eb5f2f688bc', '01235e4f-a7f8-54fa-a9c9-c6a0afe74ceb', 21, 23, 'እንደ በደላቸውም እንደ ክፋታቸውም ፍዳቸውን ይከፍላቸዋል አምላካችን እግዚአብሔርም ያጠፋቸዋል'),
  ('7bf6d79c-bd25-50e0-a9d8-b768d4777a6f', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 1, 1, 'ኑ በእግዚአብሔር ደስ ይበለን ለአምላክ ለመድኀኒታችን እልል እንበል'),
  ('625c1573-76d9-57f6-a16a-9d3665928560', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 2, 2, 'በምስጋና ወደ ፊቱ እንድረስ በዝማሬም ለርሱ እልል እንበል'),
  ('f555c123-06c5-55df-afef-cd36bfc06cea', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 3, 3, 'እግዚአብሔር ታላቅ አምላክ ነውና በአማልክትም ዅሉ ላይ ታላቅ ንጉሥ ነውና'),
  ('af13ae45-99de-5406-a215-f8c63bf3b849', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 4, 4, 'እግዚአብሔር ሕዝቡን አይጥላቸውም የምድር ዳርቻዎችም በእጁ ውስጥ ናቸው የተራራዎች ከፍታዎች የር ሱ ናቸው'),
  ('9ef1561a-1a76-5425-ab24-e7a21e39c3dd', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 5, 5, 'ባሕር የርሱ ናት ርሱም አደረጋት የብስንም እጆቹ ሠሯት'),
  ('51aa33c1-683c-5273-ac40-761aa3653228', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 6, 6, 'ኑ እንስገድ ለርሱም እንገዛ በርሱ ባደረገን በእግዚአብሔር ፊት እንንበርከክ'),
  ('1b10c995-26ec-5d02-afb1-1a88d4d5099c', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 7, 7, 'ርሱ አምላካችን ነውና እኛ የማሰማሪያው ሕዝብ የእጁም በጎች ነንና'),
  ('fc5cdbc3-42a2-55e1-ab9c-be03e0be6fc6', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 8, 8, 'በምድረ በዳ እንደ ተፈታተኑት እንዳስቈጡት ጊዜ ዛሬ ድምፁን ብትሰሙ ልባችኹን አታጽኑ'),
  ('4e1e5076-831b-56d3-a510-bd30bbe5ca01', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 9, 9, 'የተፈታተኑኝ አባቶቻችኹ ፈተኑኝ ሥራዬንም አዩ'),
  ('cdf73e70-8e98-55ff-ac58-152b80445df0', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 10, 10, 'ያችን ትውልድ አርባ ዓመት ተቈጥቻት ነበር ዅልጊዜ ልባቸው ይስታል እነርሱም መንገዴን አላወቁም አልኹ'),
  ('4deee357-1d2d-5d4b-a8bd-f24055295b85', '32e69530-1fad-5648-a4a9-98d4b5f33d4a', '9642c8b6-8243-5548-a2da-b1b085b9ad4d', 11, 11, 'ወደ ዕረፍቴም እንዳይገቡ በቍጣዬ ማልኹ'),
  ('5b5efa28-2a8f-5b1a-a18c-ec018988dc40', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 1, 1, 'ለእግዚአብሔር ዐዲስ ምስጋናን አመስግኑ ምድር ዅሉ እግዚአብሔርን አመስግኑ'),
  ('6d3148ab-f643-5539-a69b-60b8fee0269f', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 2, 2, 'እግዚአብሔርን አመስግኑ ስሙንም ባርኩ ዕለት ዕለትም ማዳኑን አውሩ'),
  ('296c8c44-67f2-5546-a1ea-1bd83659f604', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 3, 3, 'ክብሩን ለአሕዛብ ተኣምራቱንም ለወገኖች ዅሉ ንገሩ'),
  ('c49eafad-172a-56f6-a86a-3ed829127566', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 4, 4, 'እግዚአብሔር ታላቅ ምስጋናውም ብዙ ነውና በአማልክትም ዅሉ ላይ የተፈራ ነውና'),
  ('e5f518f9-e5e1-5b39-af3e-17fbdf20f7bc', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 5, 5, 'የአሕዛብ አማልክት ዅሉ አጋንንት ናቸውና እግዚአብሔር ግን ሰማያትን ሠራ'),
  ('9569d12b-14aa-56f6-a1d5-9d5c3d233ac9', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 6, 6, 'ምስጋናና ውበት በፊቱ ቅዱስነትና ግርማ በመቅደሱ ውስጥ ናቸው'),
  ('bb9ad84e-11cd-55f9-a27a-afb4d812233f', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 7, 7, 'የአሕዛብ ወገኖች ለእግዚአብሔር አምጡ ክብርና ምስጋናን ለእግዚአብሔር አምጡ'),
  ('e161fa9b-8c42-5565-a6af-87a4fb8ea8a0', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 8, 8, 'ለስሙ የሚገ፟ባ፟ ክብርን ለእግዚአብሔር አምጡ ቍርባን ያዙ ወደ አደባባዮችም ግቡ'),
  ('222dfeda-9633-5fb4-a149-23a52090f2ef', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 9, 9, 'በቅድስናው ስፍራ ለእግዚአብሔር ስገዱ ምድር ዅሉ በፊቱ ትነዋወጥ'),
  ('6f7d0d28-4ee5-5a4d-a285-718fff6f3051', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 10, 10, 'በአሕዛብ መካከል እግዚአብሔር ነገሠ በሉ እንዳይናወጥም ዓለሙን ርሱ አጸናው አሕዛብንም በቅንነ ት ይፈርዳል'),
  ('626d1e32-2bad-5df2-a816-0c40acaf991f', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 11, 11, 'ሰማያት ደስ ይበላቸው ምድርም ሐሤትን ታድርግ ባሕርና ሞላዋ ይናወጡ'),
  ('a844ad7f-ddc1-5cc9-a91b-62202d5742eb', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 12, 12, 'በረሓ በርሷም ያሉ ዅሉ ሐሤትን ያድርጉ የዱር ዛፎች ዅሉ በዚያን ጊዜ በእግዚአብሔር ፊት ደስ ይላቸዋል'),
  ('03f57db2-0619-5b0b-a818-e5a70e04870a', 'e52b27f1-f06c-5f58-ab9d-d8c0e0479599', '7ac88218-fafc-5efd-a6ac-0c63ff702489', 13, 13, 'ይመጣልና በምድር ላይ ሊፈርድ ይመጣልና ርሱም ዓለምን በጽድቅ አሕዛብንም በቅንነት ይፈርዳል'),
  ('f3f73651-3286-5947-af9b-5df40e687cb9', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 1, 1, 'እግዚአብሔር ነገሠ ምድር ሐሤትን ታድርግ ብዙ ደሴቶችም ደስ ይበላቸው'),
  ('e8f14786-596e-591f-ab0a-f240d0976c91', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 2, 2, 'ደመና ጭጋግም በዙሪያው ናቸው ጽድቅና ፍርድ የዙፋኑ መሠረት ናቸው'),
  ('fa743bd7-22a7-5e98-a5ec-01048ecdc6c0', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 3, 3, 'እሳት በፊቱ ይኼዳል ጠላቶቹንም በዙሪያው ያቃጥላል'),
  ('b06309be-b6c0-58e5-ade2-2774dc80416a', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 4, 4, 'መብረቆቹ ለዓለም አበሩ ምድር አየችና ተናወጠች'),
  ('1f0118c0-3471-5d20-a918-6ecd49f4a79d', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 5, 5, 'ተራራዎችም ከእግዚአብሔር ፊት ከምድር ዅሉ ጌታ ፊት እንደ ሠም ቀለጡ'),
  ('c6b156d3-0ec4-5981-a28a-b35025d0cd3c', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 6, 6, 'ሰማያት የርሱን ጽድቅ አወሩ አሕዛብም ዅሉ ክብሩን አዩ'),
  ('90d85c23-7676-55b8-a89d-53c8d40c635d', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 7, 7, 'ለተቀረጸ ምስል የሚሰግዱ ዅሉ በጣዖቶቻቸውም የሚመኩ ይፈሩ መላእክቱ ዅሉ ስገዱለት'),
  ('004953df-9d18-5f6a-a646-bdf5d7baaca6', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 8, 8, 'አቤቱ ስለ ፍርድኽ ጽዮን ሰምታ ደስ አላት የይሁዳም ሴት ልጆች ደስ አላቸው'),
  ('573a2394-9bf1-5496-a586-5c54d60398e0', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 9, 9, 'አንተ እግዚአብሔር በምድር ላይ ዅሉ ልዑል ነኽና በአማልክትም ዅሉ ላይ እጅግ ከፍ ከፍ ብለኻልና'),
  ('2bb47fe5-e855-5cff-a08e-851e09b4f405', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 10, 10, 'እግዚአብሔርን የምትወዱ ክፋትን ጥሉ እግዚአብሔር የቅዱሳኑን ነፍሶች ይጠብቃል ከኃጥኣንም እጅ ያድናቸዋል'),
  ('35dc6ca3-5b6f-5b28-ad90-73b118e76d2c', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 11, 11, 'ብርሃን ለጻድቃን ደስታም ለልበ ቅኖች ወጣ'),
  ('49cdec64-3bed-5c90-acac-e9569b352178', 'ac849436-2af8-595c-ae84-1f245313fe24', 'b71e74e1-c981-5114-ab4b-77a305e2e4a2', 12, 12, 'ጻድቃን በእግዚአብሔር ደስ ይበላችኹ ለቅድስናውም መታሰቢያ አመስግኑ'),
  ('8e92ab88-d8eb-5748-a32c-e13944b64218', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 1, 1, 'ለእግዚአብሔር ዐዲስ ምስጋናን አመስግኑ እግዚአብሔር ተኣምራትን አድርጓልና ቀኙ የተቀደሰም ክንዱ ለርሱ ማዳን አደረገ'),
  ('2b6e7c4e-314d-5a2a-a05e-b4ff0a718fc4', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 2, 2, 'እግዚአብሔር ማዳኑን አስታወቀ በአሕዛብም ፊት ጽድቁን ገለጠ'),
  ('6ce43ed7-5969-5d1e-a5c6-62cd065dd4fb', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 3, 3, 'ለያዕቆብ ምሕረቱን ለእስራኤልም ቤት እውነቱን ዐሰበ የምድር ዳርቻዎች ዅሉ የአምላካችንን ማዳን አዩ'),
  ('2b50feed-0dec-5a8d-ab9b-30b107b7b26f', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 4, 4, 'ምድር ዅሉ ሆይ ለእግዚአብሔር እልል በሉ አመስግኑ ደስ ይበላችኹ ዘምሩም'),
  ('19cf8a1b-7538-551a-a965-8be0668a5cbe', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 5, 5, 'ለእግዚአብሔር በመሰንቆ በመሰንቆና በዝማሬ ድምፅ ዘምሩ'),
  ('9881202f-9464-512b-ad45-8418e0972086', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 6, 6, 'በዋሽንትና በመለከት ድምፅ በንጉሥ በእግዚአብሔር ፊት እልል በሉ'),
  ('347c89a9-bc78-5fc1-ae73-bc8937151b94', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 7, 7, 'ባሕርና ሞላዋ ዓለምም በርሷም የሚኖሩ ይናወጡ'),
  ('a5ef5745-462a-5a1a-af3e-402daf69ee21', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 8, 8, 'ወንዞችም በአንድነት በእጅ ያጨብጭቡ ተራራዎች ደስ ይበላቸው በምድር ሊፈርድ ይመጣልና'),
  ('d6b4ee8a-9246-521a-ad13-dda55ec838f9', '8dcae703-a965-52f4-a6e7-54ffd561800a', '956ff12f-1b97-53e6-a2f7-dec33541b942', 9, 9, 'ለዓለምም በጽድቅ ለአሕዛብም በቅንነት ይፈርዳል'),
  ('28690fd3-8547-56ae-af37-76bcd6a4451a', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 1, 1, 'እግዚአብሔር ነገሠ አሕዛብ ይደንግጡ በኪሩቤል ላይ ተቀመጠ ምድር ትናወጥ'),
  ('83452cca-08ed-5589-a1f9-d062a9281ad6', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 2, 2, 'እግዚአብሔር በጽዮን ታላቅ ነው ርሱም በአሕዛብ ዅሉ ላይ ከፍ ከፍ አለ'),
  ('dee4f8d2-bd96-5878-ac8a-fd07f026ec0d', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 3, 3, 'ግሩምና ቅዱስ ነውና ዅሉ ታላቅ ስምኽን ያመስግኑ'),
  ('300cef6d-c896-531c-a106-de9f57c775bc', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 4, 4, 'የንጉሥ ክብር ፍርድን ይወዳ፟ል አንተ ቅንነትን አጸናኽ ለያዕቆብ ፍርድንና ጽድቅን አንተ አደረግ ኽ'),
  ('c2cec48f-e408-5206-aad1-4855d8e0adb1', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 5, 5, 'አምላካችንን እግዚአብሔርን ከፍ ከፍ አድርጉት ቅዱስ ነውና ወደእግሩ መረገጫ ስገዱ'),
  ('1af24a0f-1363-502f-a2a6-c1b655efd91b', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 6, 6, 'ሙሴና አሮን በካህናቱ ዘንድ ሳሙኤልም ስሙን በሚጠሩት ዘንድ ናቸው እግዚአብሔርን ጠሩት ርሱም መ ለሰላቸው'),
  ('1b21a008-dcb6-59af-a363-f23b142c1a48', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 7, 7, 'በደመና ዐምድም ተናገራቸው ምስክሩንና የሰጣቸውን ትእዛዝ ጠበቁ'),
  ('d84412e1-6db9-54b6-ae82-f122ba7b04df', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 8, 8, 'አቤቱ አምላክችን ሆይ አንተ ሰማኻቸው አቤቱ አንተ ማርኻቸው ሥራቸውን ዅሉ ግን ተበቀልኻቸው'),
  ('c03e2c31-a72a-56db-aa91-6a067f1e7c08', '336e4306-5a47-543f-af7a-c20f1fba053e', '0921c529-6e61-5af0-af46-f892599d1a97', 9, 9, 'አምላካችንን እግዚአብሔርን ከፍ ከፍ አድርጉት በቅዱስ ተራራውም ስገዱ አምላካችን እግዚአብሔር ቅ ዱስ ነውና'),
  ('4291bdae-79d0-5f85-a45b-0839f6def9e2', 'd93b7c83-7cba-5aeb-acf4-1171faa80884', '103ce90a-cb70-54c8-a360-4d811a1d6926', 1, 1, 'ምድር ዅሉ ለእግዚአብሔር እልል በሉ'),
  ('e02ea007-cdf5-55c1-afde-236c3b0574fe', 'd93b7c83-7cba-5aeb-acf4-1171faa80884', '103ce90a-cb70-54c8-a360-4d811a1d6926', 2, 2, 'በደስታም ለእግዚአብሔር ተገዙ በሐሤትም ወደ ፊቱ ግቡ'),
  ('c035f6ef-f570-5632-ae28-b2a6c999e0c2', 'd93b7c83-7cba-5aeb-acf4-1171faa80884', '103ce90a-cb70-54c8-a360-4d811a1d6926', 3, 3, 'እግዚአብሔር ርሱ አምላክ እንደ ኾነ ዕወቁ ርሱ ሠራን እኛም አይደለንም እኛስ ሕዝቡ የማሰማሪያው ም በጎች ነን'),
  ('870f5a22-02a8-5f1e-a8bc-306028cfb860', 'd93b7c83-7cba-5aeb-acf4-1171faa80884', '103ce90a-cb70-54c8-a360-4d811a1d6926', 4, 4, 'ወደ ደጆቹ በመገዛት ወደ አደባባዮቹም በምስጋና ግቡ አመስግኑት ስሙንም ባርኩ'),
  ('ec86a64d-457b-561b-aa4c-3b2ecd0c7e49', 'd93b7c83-7cba-5aeb-acf4-1171faa80884', '103ce90a-cb70-54c8-a360-4d811a1d6926', 5, 5, 'እግዚአብሔር ቸር ምሕረቱም ለዘለዓለም እውነቱም ለልጅ ልጅ ነውና'),
  ('9eec7b39-8bd6-5574-a353-348affa35321', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 1, 1, 'አቤቱ ምሕረትንና ፍርድን እቀኝልኻለኹ'),
  ('aedcc062-9677-5050-af89-aa8d3f22be4e', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 2, 2, 'እዘምራለኹ ንጹሕ መንገዱንም አስተውላለኹ ወደ እኔ መቼ ትመጣለኽ በቤቴ መካከል በልቤ ቅንነት እ ኼዳለኹ'),
  ('c9bab15e-e35e-5d4e-afce-014b2434a191', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 3, 3, 'በዐይኔ ፊት ክፉን ነገር አላኖርኹም ሕግ ተላላፊዎችን ጠላኹ'),
  ('25d2fbf6-a70b-5661-afe6-8caa8a9c6237', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 4, 4, 'ጠማማ ልብም አልተጠጋኝም ክፉ ከእኔ በራቀ ጊዜ አላወቅኹም'),
  ('281c8078-40f3-5419-ad73-6e920b06fb10', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 5, 5, 'ባልንጀራውን በቀስታ የሚያማን ርሱን አሳደድኹ በዐይኑ ትዕቢተኛ የኾነውና ልቡ የሚሣሣው ከእኔ ጋ ራ አይተባበርም'),
  ('1b64b4d4-c431-5ebe-a114-60ec58c789da', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 6, 6, 'ከእኔ ጋራ ይኖሩ ዘንድ ዐይኖቼ በምድር ምእመናን ላይ ናቸው በቀና መንገድ የሚኼድ ርሱ ያገለግለ ኛል'),
  ('53809e34-ecbb-5f2e-a565-4aae0be37cac', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 7, 7, 'ትዕቢትን የሚያደርግ በቤቴ መካከል አይኖርም ዐመፅን የሚናገር በዐይኔ ፊት አይቀናም'),
  ('f198f621-d462-5826-a1ef-5cabebc49cf3', '2ce29ccf-3430-5615-abe2-01e615b025dd', '3a8b8151-8bad-550c-a75d-2dbef431f616', 8, 8, 'ዐመፃ የሚያደርጉትን ዅሉ ከእግዚአብሔር ከተማ አጠፋቸው ዘንድ የምድርን ኀጢአተኛዎች ዅሉ በማለዳ እገድላቸዋለኹ'),
  ('0db5f697-0b2b-509b-a632-70ef1416e535', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 1, 1, 'አቤቱ ጸሎቴን ስማኝ ጩኸቴም ወዳንተ ይድረስ'),
  ('6b8a10d5-e36a-5be2-a6cc-4a7409690c9d', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 2, 2, 'በመከራዬ ቀን ፊትኽን ከእኔ አትመልስ ዦሮኽን ወደ እኔ አዘንብል በጠራኹኽ ቀን ፈጥነኽ ስማኝ'),
  ('18de3651-7123-5bf4-af1f-52a8335a5edf', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 3, 3, 'ዘመኔ እንደ ጢስ አልቃለችና ዐጥንቶቼም እንደ መቃጠያ ተቃጥለዋልና'),
  ('877d6076-ebb1-563f-a8b9-4c60db063176', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 4, 4, 'እኽል መብላት ተረስቶኛልና ተቀሠፍኹ ልቤም እንደ ሣር ደረቀ'),
  ('5b529388-1f91-5893-af08-1ef76b528b90', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 5, 5, 'ከጩኸቴ ድምፅ የተነሣ ዐጥንቶቼ ከሥጋዬ ጋራ ተጣበቁ'),
  ('199db01d-48cd-5093-a90d-1436608e7ba4', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 6, 6, 'እንደ ምድረ በዳ እርኩም መሰልኹ በፈረሰ ቤት እንዳለ እንደ ጕጕት ኾንኹ'),
  ('2c224ca1-3161-5cfa-ad82-170c4f78376e', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 7, 7, 'ተጋኹ በሰገነትም እንደሚኖር ብቸኛ ድንቢጥ ኾንኹ'),
  ('f2e69dd7-3e2d-5572-ad9a-769903c704f3', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 8, 8, 'ጠላቶቼ ዅልጊዜ ይሰድቡኛል የሚያሳድዱኝም ተማማሉብኝ'),
  ('aaf55f89-776b-5d61-a225-e10b7f6f22e7', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 9, 9, 'ዐመድን እንደ እኽል ቅሜያለኹና መጠጤንም ከእንባዬ ጋራ ቀላቅያለኹና'),
  ('c1b8fb65-9677-53a6-a594-2fc3719e54df', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 10, 10, 'ከቍጣኽና ከመዓትኽም የተነሣ አንሥተኸኛልና ጥለኸኝማልና'),
  ('cb7c0d4e-0df9-5037-a51a-698c62705223', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 11, 11, 'ዘመኖቼ እንደ ጥላ አዘንብለዋል እኔም እንደ ሣር ደርቄያለኹ')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('6070e76c-c76f-525e-ae0c-d49a9aa8fb79', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 12, 12, 'አንተ ግን አቤቱ ለዘለዓለም ትኖራለኽ መታሰቢያኽም ለልጅ ልጅ ነው'),
  ('13b2dded-00c5-5eb2-a49e-1f1ce17ec484', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 13, 13, 'አንተ ተነሥ ጽዮንንም ይቅር በላት የምሕረቷ ጊዜ ነውና ዘመኗም ደርሷልና'),
  ('f831b7f2-84b6-54b9-a8bb-a6014d5a17a9', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 14, 14, 'ባሪያዎችኽም ድንጋዮቿን ወደ፟ዋልና ለመሬቷም አዝነዋልና'),
  ('6d20575b-7094-5f56-ad14-c41eb9477866', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 15, 15, 'አቤቱ አሕዛብ ስምኽን ነገሥታትም ዅሉ ክብርኽን ይፈራሉ'),
  ('d43ea777-c40d-5ba1-a587-87a776e0e048', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 16, 16, 'እግዚአብሔር ጽዮንን ይሠራታልና በክብሩም ይገለጣልና'),
