  ('27b0eec6-c3a1-5ee0-a0fc-b06d35736c71', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 20, 20, 'የእስረኛዎችን ጩኸት ይሰማ ዘንድ ሊገድሉ የተፈረደባቸውን ያድን ዘንድ'),
