  ('3370f849-7d4e-55bb-abc7-45f353df9713', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 27, 27, 'አንተ ግን ያው አንተ ነኽ ዓመቶችኽም ከቶ አያልቁም'),
  ('d9c29f08-3a36-5a55-aa3d-459d1686e0d3', '02ca26da-956d-5f2a-a67b-021a8537b95a', '28172493-2b69-5b27-acae-64763763b7f2', 28, 28, 'የባሪያዎችኽም ልጆች ይኖራሉ ዘራቸውም ለዘለዓለም ትጸናለች'),
