  ('6d64f1c6-cdf1-533c-ab26-f2bbd7f8555d', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 8, 8, 'ወደ ተራራዎች ይወጣሉ ወደ ቈላዎች ወዳዘጋጀኽላቸው ስፍራ ይወርዳሉ'),
  ('6dfab72b-2a2f-51b2-a07b-f6b08123f60e', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 9, 9, 'እንዳያልፉትም ድንበር አደረግኽላቸው ምድርን ይከድኑ ዘንድ እንዳይመለሱ'),
  ('f45c0039-6195-577f-aede-47de3ca84da5', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 10, 10, 'ምንጮችን ወደ ቈላዎች ይልካል በተራራዎች መካከል ውሃዎች ያልፋሉ'),
