  ('411ea5c9-9205-5faa-aa83-10a4ba3a47cc', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 12, 12, 'የሰማይም ወፎች በእነርሱ ዘንድ ያድራሉ በድንጋዩ ስንጥቅ መካከልም ይጮኻሉ'),
  ('9b4b5438-a19d-5c78-a21b-bac191f0ef12', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 13, 13, 'ተራራዎችን ከላይ የሚያጠጣቸው ከሥራኽ ፍሬ ምድር ትጠግባለች'),
  ('e5543f82-45d4-55b4-a73a-316411c17763', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 14, 14, 'እንጀራን ከምድር ያወጣ ዘንድ ለምለሙን ለሰው ልጆች ጥቅም ሣርንም ለእንስሳ ያበቅላል'),
  ('05cb09cb-bac5-5820-aa97-45a9596ddbd6', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 15, 15, 'ወይን የሰውን ልብ ደስ ያሰኛል ዘይትም ፊትን ያበራል እኽልም የሰውን ጕልበት ያጠነክራል'),
  ('94c27158-5009-5433-ab3e-9b8dff4430c5', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 16, 16, 'የእግዚአብሔር ዛፎች ርሱም የተከላቸው የሊባኖስ ዝግባዎች ይጠግባሉ'),
  ('695dadcf-ba7e-54d6-a93e-8cba7251cd8b', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 17, 17, 'በዚያም ወፎች ይዋለዳሉ የሽመላ ቤትም የእነርሱ ጎረቤት ነው'),
  ('96d30bdd-133e-52d7-a3e2-75192c6d2f6b', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 18, 18, 'ረዣዥም ተራራዎች ለዋላዎች ድንጋዮችም ለሽኮኮዎች መሸሻ ናቸው'),
  ('ec69dc6d-10d5-5b4b-a809-d4048e5bfb79', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 19, 19, 'ጨረቃን ለጊዜዎች አደረገ ፀሓይም መግቢያውን ያውቃል'),
