  ('be42fa27-7e16-5f19-ada9-4e4b9cc90000', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 21, 21, 'የአንበሳ ግልገሎች ለመንጠቅ ይጮኻሉ ከእግዚአብሔርም ምግባቸውን ይሻሉ'),
  ('9787b0c1-cb90-5a0a-aa44-f02966a9f01b', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 22, 22, 'ፀሓይ ስትወጣ ይሰበሰባሉ በየዋሻቸውም ይተኛሉ'),
  ('7b277dbf-1260-5ee3-a3f1-47a8a491823c', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 23, 23, 'ሰው ወደ ተግባሩ እስኪመሽም ድረስ ወደ ሥራው ይወጣል'),
  ('caebd829-ec82-5460-aa06-c4b6bdf6de1a', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 24, 24, 'አቤቱ ሥራኽ እጅግ ብዙ ነው ዅሉን በጥበብ አደረግኽ ምድርም ከፍጥረትኽ ተሞላች'),
  ('d17219d1-2474-579d-a15c-ac359fa8958f', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 25, 25, 'ይህች ባሕር ታላቅና ሰፊ ናት በዚያ ስፍራ ቍጥር የሌለው ተንቀሳቃሽ ታላላቆችና ታናናሾች እንስ ሳዎች አሉ'),
  ('8cccd0b2-516c-5848-a181-8d87fde6fe37', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 26, 26, 'በዚያ ጊዜ መርከቦች ይኼዳሉ በዚያም ላይ የፈጠርኸው ዘንዶ ይጫወትበታል'),
