  ('7323fbcf-4865-5573-aa19-293ca4d54a03', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 28, 28, 'በሰጠኻቸውም ጊዜ ይሰበስባሉ እጅኽን ትከፍታለኽ ከመልካም ነገርም ይጠግባሉ'),
  ('1a367659-e17b-57a5-ae1e-dd35cba3310d', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 29, 29, 'ፊትኽን ስትሰውር ይደነግጣሉ ነፍሳቸውን ታወጣለኽ ይሞታሉም ወደ ዐፈራቸውም ይመለሳሉ'),
  ('74bf6bdc-a087-5532-ad85-41f5fcaa2e1d', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 30, 30, 'መንፈስኽን ትልካለኽ ይፈጠራሉም የምድርንም ፊት ታድሳለኽ'),
  ('c4f8f1da-700a-5bd7-ab86-e1eff895816a', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 31, 31, 'የእግዚአብሔር ክብር ለዘላለም ይኹን እግዚአብሔር በሥራው ደስ ይለዋል'),
