  ('f1cd6eb2-0545-5fc3-afb0-8e70b36a7429', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 33, 33, 'በሕይወቴ ሳለኹ ለእግዚአብሔር እቀኛለኹ ለአምላኬም በምኖርበት ዘመን ዅሉ እዘምራለኹ'),
