  ('7d20cf66-8563-5b90-a74a-e33e9731c81f', '9f6311ff-8af8-5773-a199-5c77802154bd', 'e0d17cb5-bfa5-5011-ad37-c57ff184aa89', 35, 35, 'ኃጥኣን ከምድር ይጥፉ ዐመፀኛዎች እንግዲህ አይገኙ ነፍሴ ሆይ እግዚአብሔርን ባርኪ ሃሌ ሉያ'),
  ('b9b9d181-2f9e-5ecd-a441-562a6e79f2d4', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 1, 1, 'እግዚአብሔርን አመስግኑ ስሙንም ጥሩ ለአሕዛብም ሥራውን አውሩ'),
  ('3b2cd00b-1f10-5acd-a52e-7a1b39228025', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 2, 2, 'ተቀኙለት ዘምሩለት ተኣምራቱንም ዅሉ ተናገሩ'),
  ('57df9bcc-6b86-59c1-aac8-e4686e0301e2', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 3, 3, 'በቅዱስ ስሙ ተጓደዱ እግዚአብሔርን የሚፈልግ ልብ ደስ ይበለው'),
  ('1e4e4a8b-50a5-53da-a398-3efd40e4b9e5', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 4, 4, 'እግዚአብሔርን ፈልጉት ትጸናላችኹም ዅልጊዜ ፊቱን ፈልጉ 5-6 ባሪያዎቹ የአብርሃም ዘር ለርሱም የተመረጣችኹ የያዕቆብ ልጆች ሆይ የሠራትን ድንቅ ዐስቡ ተኣም ራቱን የአፉንም ፍርድ'),
  ('b3bc3a26-6d9d-595c-a653-4ca8601f77ae', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 5, 7, 'ርሱ እግዚአብሔር አምላካችን ነው ፍርዱ በምድር ዅሉ ነው'),
  ('5e096947-7cac-52f7-a20b-3535b022698f', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 6, 8, 'ቃል ኪዳኑን ለዘለዓለም እስከ ሺሕ ትውልድ ያዘዘውን ቃሉን ዐሰበ'),
  ('82d58b87-7844-514e-a9bf-f430b9fe71a9', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 7, 9, 'ለአብርሃም ያደረገውን ለይሥሐቅም የማለውን'),
  ('535c0ac7-db7e-5f9f-a5e4-d266781e60a0', '928fd957-bec6-5505-ada8-160be8456074', 'b76c73f6-7c21-53ae-adb5-4daba97f39d5', 8, 10, 'ለያዕቆብ ሥርዐት እንዲኾን ለእስራኤልም የዘለዓለም ኪዳን እንዲኾን አጸና'),
