  ('583fd206-d914-55f2-afd7-fe0c81d8af5e', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 8, 8, 'ኀይሉን ግን ለማስታወቅ ስለ ስሙ አዳናቸው'),
