  ('4b25ba99-b28e-5f98-a6de-d1cd78a2a345', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 10, 10, 'ከሚጠሏቸውም እጅ አዳናቸው ከጠላትም እጅ ተቤዣቸው'),
  ('bf4443ab-b9a1-57b6-a6fa-4c33b534f902', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 11, 11, 'ያሳደዷቸውንም ውሃ ደፈናቸው ከነርሱም አንድ አልቀረም'),
  ('7358acfb-f50c-5524-a874-9b6686335079', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 12, 12, 'በዚያን ጊዜ በቃሉ አመኑ ምስጋናውንም ዘመሩ'),
  ('83628cf4-37a9-5092-a958-4c1454f38334', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 13, 13, 'ፈጥነውም ሥራውን ረሱ በምክሩም አልታገሡም'),
  ('b3a26862-d002-5bfc-ad71-b52894a8b509', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 14, 14, 'በምድረ በዳም ምኞትን ተመኙ በበረሓም እግዚአብሔርን ተፈታተኑት'),
  ('6cdc8560-bd1c-5fe0-a3b9-8a43cdb61365', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 15, 15, 'የለመኑትንም ሰጣቸው ለነፍሳቸው ግን ክሳትን ላከ'),
  ('62e4dd11-04c3-5868-a68b-1ea4b9d044b0', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 16, 16, 'ሙሴንም እግዚአብሔር የቀደሰውንም አሮንን በሰፈር ተመቀኟቸው'),
  ('d9ac8d63-0e94-5886-a2f1-bf5d6fc9658d', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 17, 17, 'ምድርም ተከፈተች ዳታንንም ዋጠችው የአቤሮንንም ወገን ደፈነች'),
  ('1fef171d-2c1f-55c0-afa8-6d7686c9443a', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 18, 18, 'በማኅበራቸውም እሳት ነደደች ነበልባልም ኃጥኣንን አቃጠላቸው'),
  ('b797c999-8ac9-55fe-a3b7-3bfe3bdc503a', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 19, 19, 'በኰሬብም ጥጃን ሠሩ ቀልጦ ለተሠራ ምስልም ሰገዱ'),
  ('111c1e7e-ba1d-5b46-a065-70810e79d527', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 20, 20, 'ሣርም በሚበላ በበሬ ምሳሌ ክብራቸውን ለወጡ 21-22 ታላቅ ነገርንም በግብጽ ድንቅንም በካራን ምድር ግሩም ነገርንም በቀይ ባሕር ያደረገውን ያዳና ቸውንም እግዚአብሔርን ረሱ'),
  ('d81434ff-d381-5945-a96a-d3994a0cca2f', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 21, 23, 'እንዳያጠፋቸው ቍጣውን ይመልስ ዘንድ የተመረጠው ሙሴ በመቅሠፍት ጊዜ በፊቱ ባይቆም ኖሮ ያጠፋቸ ው ዘንድ ተናገረ'),
  ('70bd75fe-d250-5d5f-aad0-3eb95b673775', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 22, 24, 'የተወደደችውን ምድር ናቁ በቃሉም አልታመኑም'),
  ('c7eb18d3-c6b9-519f-a138-56ebddd6659e', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 23, 25, 'በድንኳኖቻቸውም ውስጥ አንጐራጐሩ የእግዚአብሔርን ቃል አልሰሙም 26-27 በምድረ በዳም ይጥላቸው ዘንድ ዘራቸውንም በአሕዛብ መካከል ይጥል ዘንድ በያገሩም ይበትናቸው ዘንድ እጁን አነሣባቸው'),
  ('4d0304fd-79e9-52a9-ac70-4dfca91f72b2', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 24, 28, 'በብዔል ፌጎርም ተባበሩበት የሙታንንም መሥዋዕት በሉ'),
  ('e8456b32-47b9-5be6-a0dc-c99f78d308fd', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 25, 29, 'በሥራቸውም አስመረሩት ቸነፈርም በላያቸው በዛ'),
  ('2cda3eae-6dff-5ef3-a74b-dec58b8c9d16', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 26, 30, 'ፊንሐስም ተነሥቶ ፈረደባቸው ቸነፈሩም ተወ'),
  ('67e760f4-5a02-5fab-a904-d4a1bcd87072', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 27, 31, 'ያም እስከ ዘለዓለም ለልጅ ልጅ ጽድቅ ኾኖ ተቈጠረለት 32-33 በክርክር ውሃ ዘንድም አስቈጡት መንፈሱን አስመርረዋታልና ስለ እነርሱም ሙሴ ተበሳጨ በከንፈሮ ቹም በስንፍና ተናገረ'),
  ('bd91c1bd-4222-54fa-ab43-40e9994b5304', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 28, 34, 'እግዚአብሔርም እንዳላቸው አሕዛብን አላጠፉም'),
  ('3dd94e16-e73e-5628-a753-f9992b3ee4c5', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 29, 35, 'ከአሕዛብም ጋራ ተደባለቁ ሥራቸውንም ተማሩ'),
  ('e7cc0382-5349-528e-a7aa-8b5e20c1863d', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 30, 36, 'ለጣዖቶቻቸውም ተገዙ ወጥመድም ኾኑባቸው'),
  ('0ecf0d95-3a03-535b-a18f-58ccbf48cc3c', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 31, 37, 'ወንዶች ልጆቻቸውንና ሴቶች ልጆቻቸውን ለአጋንንት ሠዉ'),
  ('3169a6af-a8f2-5041-a457-02306d3f8670', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 32, 38, 'የወንዶች ልጆቻቸውንና የሴቶች ልጆቻችን ደም ለከነዓን ጣዖቶች የሠዉአቸውን ንጹሕ ደም አፈሰሱ ምድርም በደም ረከሰች'),
  ('10af63bb-7c8a-5db3-a54c-f181f6f6ea21', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 33, 39, 'በሥራቸው ረከሱ በማድረጋቸውም አመነዘሩ'),
  ('9e67ce6c-a614-55db-a7d8-a5863f72d1d1', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 34, 40, 'የእግዚአብሔርም ቍጣ በሕዝቡ ላይ ነደደ ርስቱንም ተጸየፈ'),
  ('b56fa7d4-d6c9-5d71-ade1-8cbd60f25282', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 35, 41, 'ወደ አሕዛብም እጅ አሳለፋቸው የሚጠሏቸውም ገዟቸው'),
  ('0d937f5e-7123-5abe-a838-67c38d0c2657', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 36, 42, 'ጠላቶቻቸውም ግፍ አደረጉባቸው ከእጃቸውም በታች ተዋረዱ'),
  ('5d1e4a56-cf96-5bde-a1b9-34ea46cebdb1', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 37, 43, 'ብዙ ጊዜ አዳናቸው ነገር ግን በምክራቸው አስመረሩት በኀጢአታቸውም ተዋረዱ'),
  ('207a731f-3b19-550c-ae32-bec49980877b', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 38, 44, 'ርሱ ግን ጩኸታቸውን በሰማ ጊዜ ጭንቃቸውን ተመለከተ'),
  ('205fa0a4-7458-568f-a10d-f6be9aa301d9', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 39, 45, 'ለእነርሱም ኪዳኑን ዐሰበ እንደ ምሕረቱም ብዛት ተጸጸተ'),
  ('d24d670a-5ed7-5ffc-a064-c4402edcf6be', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 40, 46, 'በማረኳቸውም ዅሉ ፊት ሞገስን ሰጣቸው'),
  ('dd0f9371-f619-5fe3-a625-6030fef1e4b7', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 41, 47, 'አምላካችን እግዚአብሔር ሆይ አድነን ቅዱስ ስምኽን እናመሰግን ዘንድ በምስጋናኽም እንመካ ዘንድ ከአሕዛብ መካከል ሰብስበን'),
  ('66165ccc-4305-5a08-a2c9-8a3ccbff74e9', '2f6ded25-e09a-56d8-af10-96b26d3a0a8b', 'b6830a8d-3090-5f40-ac8e-ff37dc517253', 42, 48, 'ከዘለዓለም እስከ ዘለዓለም የእስራኤል አምላክ እግዚአብሔር ይባረክ ሕዝብም ዅሉ አሜን ይበል ሃ ሌ ሉያ'),
  ('03e22d38-c744-5f7e-a6d6-f2d5a023c5dc', '8b845625-07e4-5efe-a26f-e785c5389c0c', '51869c92-933f-54cb-a641-28e0f089fed2', 1, 1, 'ቸር ነውና ምሕረቱ ለዘለዓለም ነውና እግዚአብሔርን አመስግኑ'),
  ('940ac2d2-3b2f-5f81-a18d-eaeac46553fe', '8b845625-07e4-5efe-a26f-e785c5389c0c', '51869c92-933f-54cb-a641-28e0f089fed2', 2, 2, 'እግዚአብሔር ያዳናቸው ከጠላቶች እጅ ያዳናቸው ይናገሩ'),
  ('175e619d-a0db-5ba4-a624-b1debc6d328f', '8b845625-07e4-5efe-a26f-e785c5389c0c', '51869c92-933f-54cb-a641-28e0f089fed2', 3, 3, 'ከምሥራቅና ከምዕራብ ከሰሜንና ከባሕር ከየአገሩ ሰበሰባቸው'),
  ('11af26d9-fc0c-5ad3-ab8d-e7909657647b', '8b845625-07e4-5efe-a26f-e785c5389c0c', '51869c92-933f-54cb-a641-28e0f089fed2', 4, 4, 'ውሃ በሌለበት ምድረ በዳ ተቅበዘበዙ የሚኖሩበትንም ከተማ መንገድ አላገኙም'),
  ('a4a37fda-2918-5b9d-a51a-d8b4cd754d03', '8b845625-07e4-5efe-a26f-e785c5389c0c', '51869c92-933f-54cb-a641-28e0f089fed2', 5, 5, 'ተራቡ ተጠሙም ነፍሳቸውም በውስጣቸው አለቀች'),
