  ('02d4cf49-2b0f-57fe-a0c0-0e2b508b2a12', '92be165b-c3d9-5086-ad42-7f6f2020470e', '3ae785ab-ce8f-502d-ad0b-8745fa001be8', 7, 7, 'እግዚአብሔር በቅድስናው ተናገረ፦ደስ ይለኛል ሴኬምንም እካፈላለኹ የሱኮትንም ሸለቆ እሰፍራለኹ'),
  ('4c961f42-b210-528a-a463-6713a32b3a24', '92be165b-c3d9-5086-ad42-7f6f2020470e', '3ae785ab-ce8f-502d-ad0b-8745fa001be8', 8, 8, 'ገለዓድ የእኔ ነው ምናሴም የእኔ ነው ኤፍሬም የራሴ መጠጊያ ነው ይሁዳ ንጉሤ ነው'),
  ('7853ebf9-0ebe-5649-a6e4-d9ecc37c20d7', '92be165b-c3d9-5086-ad42-7f6f2020470e', '3ae785ab-ce8f-502d-ad0b-8745fa001be8', 9, 9, 'ሞዐብ መታጠቢያዬ ነው በኤዶምያስ ላይም ጫማዬን እዘረጋለኹ ፍልስጥኤም ይገዙልኛል'),
  ('3d7f83fe-7ae2-5e2e-ae56-de25ba0349cb', '92be165b-c3d9-5086-ad42-7f6f2020470e', '3ae785ab-ce8f-502d-ad0b-8745fa001be8', 10, 10, 'ወደ ጽኑ ከተማ ማን ይወስደኛል ማንስ እስከ ኤዶምያስ ይመራኛል'),
  ('954ef974-c0ea-51c6-aa72-60bdc98e9920', '92be165b-c3d9-5086-ad42-7f6f2020470e', '3ae785ab-ce8f-502d-ad0b-8745fa001be8', 11, 11, 'አቤቱ የጣልኸኝ አንተ አይደለኽምን አምላክ ሆይ ከሰራዊታችን ጋራ አትወጣም'),
  ('248d7016-946c-58aa-a21f-828ab4e4ca90', '92be165b-c3d9-5086-ad42-7f6f2020470e', '3ae785ab-ce8f-502d-ad0b-8745fa001be8', 12, 12, 'በመከራችን ረድኤትን ስጠን የሰውም ማዳን ከንቱ ነው'),
  ('67f01dce-0f54-50b3-affb-1235ca264b97', '92be165b-c3d9-5086-ad42-7f6f2020470e', '3ae785ab-ce8f-502d-ad0b-8745fa001be8', 13, 13, 'በእግዚአብሔር ኀይልን እናደርጋለን ርሱም የሚያስጨንቁንን ያዋርዳቸዋል'),
  ('825d8a8b-b1cf-5985-ac8e-fe0544116635', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 1, 1, 'አምላክ ሆይ ምስጋናዬን ዝም አትበል'),
