  ('345055f3-462b-5b6e-a247-1a974cc6bde0', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 3, 3, 'በጥል ቃል ከበቡኝ በከንቱም ተሰለፉብኝ'),
  ('812d7dcf-d37b-540c-a24e-4fe28cddc80e', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 4, 4, 'በወደድዃቸው ፋንታ አጣሉኝ እኔ ግን እጸልያለኹ'),
  ('186d2f44-0b4c-5ff4-a724-2dba49367803', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 5, 5, 'በመልካም ፋንታ ክፉን በወደድዃቸውም ፋንታ ጠላትነትን መለሱልኝ'),
  ('f388debe-f48b-5cd7-a703-901c02f1341e', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 6, 6, 'በላዩ ኀጢአተኛን ሹም ሰይጣንም በቀኙ ይቁም'),
  ('f546a027-0734-53ab-af51-d912a380863c', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 7, 7, 'በተሟገተም ጊዜ ተረቶ፟ ይውጣ ጸሎቱም ኀጢአት ትኹንበት'),
  ('bd5703e2-9cb2-578b-a339-303d5277629a', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 8, 8, 'ዘመኖቹም ጥቂት ይኹኑ ሹመቱንም ሌላ ይውሰድ'),
  ('db3f5e0f-b2b8-52e8-a509-338573867f4a', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 9, 9, 'ልጆቹም ድኻ አደግ ይኹኑ ሚስቱም መበለት ትኹን'),
  ('8ef84a1c-887e-5452-a9a6-03110cdc9337', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 10, 10, 'ልጆቹም ተናውጠው ይቅበዝበዙ ይለምኑም ከስፍራቸውም ይባረሩ'),
  ('e4255c8f-669f-5471-ae8a-0758adc84f18', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 11, 11, 'ባለዕዳም ያለውን ዅሉ ይበርብረው እንግዳዎችም ድካሙን ዅሉ ይበዝብዙት'),
  ('1a5496c1-c5b1-5e1e-adc7-001e058bee92', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 12, 12, 'የሚያግዘውንም አያግኝ ለድኻ አደግ ልጆቹም የሚራራ አይኑር'),
  ('3f0e52a2-7cd3-507c-a2cb-645c8fd7ca94', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 13, 13, 'ልጆቹ ይጥፉ ባንድ ትውልድ ስሙ ይደምሰስ'),
