  ('8219a90c-80dd-546e-a567-fa6bffcc2ce7', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 15, 15, 'በእግዚአብሔር ፊት ዅልጊዜ ይኑሩ መታሰቢያቸው ከምድር ይጥፋ'),
  ('70260318-c6d3-5c1a-aa33-db126e5ce23c', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 16, 16, 'ምሕረትን ያደርግ ዘንድ አላሰበምና ችግረኛንና ምስኪንን ልቡ የተሰበረውንም ሰው ይገድል ዘንድ አሳደደ'),
  ('e9733e3e-7c6f-5693-abb5-44cb70c93ddc', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 17, 17, 'መርገምን ወደደ ወደ ርሱም መጣች በረከትንም አልመረጠም ከርሱም ራቀች'),
  ('43c17fbd-6637-535e-a409-2a70c85fb970', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 18, 18, 'መርገምን እንደ ልብስ ለበሳት እንደ ውሃም ወደ አንዠቱ እንደ ቅባትም ወደ ዐጥንቱ ገባች'),
  ('4cb7138d-0bf7-5145-a5d4-785ed1788d42', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 19, 19, 'እንደሚለብሰው ልብስ ዅልጊዜም እንደሚታጠቀው ትጥቅ ይኹነው'),
  ('f0b87b1c-c4b1-5d53-a580-7068870c488c', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 20, 20, 'ይህ ሥራ ከእግዚአብሔር ዘንድ በሚያጣሉኝ በነፍሴም ላይ ክፉን በሚናገሩ ነው'),
  ('daa95b86-e740-536f-a5e2-01fbf1f0e151', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 21, 21, 'አንተ ግን አቤቱ ጌታዬ ስለ ስምኽ ምሕረትኽን በእኔ ላይ አድርግ ምሕረትኽ መልካም ናትና አድነ ኝ'),
  ('7130aab9-6015-59f6-aa76-aee7def3b55d', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 22, 22, 'እኔ ችግረኛ ምስኪንም ነኝና ልቤም በውስጤ ደነገጠብኝ'),
  ('d2c773dd-9b21-58bc-abb5-5b93baf816dc', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 23, 23, 'እንዳለፈ ጥላ አለቅኹ እንደ አንበጣም ረገፍኹ'),
  ('34ea95d0-9383-5a4c-a565-4d01decd0f7d', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 24, 24, 'ጕልበቶቼ በጾም ደከሙ ሥጋዬም ቅቤ በማጣት ከሳ'),
  ('e646867b-9fe7-5a49-addc-b8e4a5babe30', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 25, 25, 'እኔም በእነርሱ ዘንድ ለነውር ኾንኹ ባዩኝ ጊዜ ራሳቸውን ነቀነቁ'),
  ('48386c1f-ff11-55a9-a5a5-b5ecab1f5a43', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 26, 26, 'አቤቱ አምላኬ ርዳኝ እንደ ምሕረትኽም አድነኝ'),
  ('6f619853-084e-5c47-a39d-d57165aa66f1', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 27, 27, 'አቤቱ እጅኽ ይህች እንደ ኾነች አንተም ይህችን እንዳደረግኽ ይወቁ'),
  ('c3c6027b-abcf-5977-aabc-8c1ad7b6f80d', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 28, 28, 'እነርሱ ይራገማሉ አንተ ግን ባርክ በእኔ ላይ የሚነሡ ይፈሩ ባሪያኽ ግን ደስ ይበለው'),
  ('c2bc6f1b-59e4-5f25-af85-ed930cffaf1e', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 29, 29, 'የሚያጣሉኝ ዕፍረትን ይልበሱ ዕፍረታቸውን እንደ መጐናጸፊያ ይልበሷት'),
  ('c113682a-6469-5289-ae05-2f128f3884a5', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 30, 30, 'እግዚአብሔርን በአፌ እጅግ አመሰግነዋለኹ በብዙዎችም መካከል አከብረዋለኹ'),
  ('85b5a4b2-faf8-5562-a5fe-3d7685aad85a', 'f95adee2-e0b4-5377-a9b5-3a70fcbabd4f', 'd6bde3e9-135c-5eba-a6fa-e0cdbe470f6d', 31, 31, 'ነፍሱን ከሚያሳድዷት ያድን ዘንድ በድኻ ቀኝ ቆሟልና'),
  ('a084b1cd-663e-5622-a025-339babc6c261', 'b1f06aec-ee7c-5fd7-a1e7-0672ecaac918', '88d7de3e-70c6-53a9-a166-9fd38bd1817b', 1, 1, 'እግዚአብሔር ጌታዬን፦ጠላቶችኽን ለእግርኽ መቀመጫ እስካደርግልኽ ድረስ በቀኜ ተቀመጥ አለው'),
  ('650568f6-c491-52b0-a3e0-7f6dcbeba5e9', 'b1f06aec-ee7c-5fd7-a1e7-0672ecaac918', '88d7de3e-70c6-53a9-a166-9fd38bd1817b', 2, 2, 'እግዚአብሔር የኀይልን በትር ከጽዮን ይልክልኻል በጠላቶችኽም መካከል ግዛ'),
  ('adc39548-cda4-5a89-a61d-9ddf1b1b8d34', 'b1f06aec-ee7c-5fd7-a1e7-0672ecaac918', '88d7de3e-70c6-53a9-a166-9fd38bd1817b', 3, 3, 'ከአንተ ጋራ ቀድሞ በኀይልኽ ቀን በቅዱሳን ብርሃን ከአጥቢያ ኮከብ አስቀድሞ ከሆድ ወለድኹኽ'),
  ('d6c9b985-23f5-5a5e-ab6c-f05435c2965e', 'b1f06aec-ee7c-5fd7-a1e7-0672ecaac918', '88d7de3e-70c6-53a9-a166-9fd38bd1817b', 4, 4, 'እንደ መልከ ጼዴቅ ሥርዐት አንተ ለዘለዓለም ካህን ነኽ ብሎ እግዚአብሔር ማለ አይጸጸትም'),
  ('ad089bc9-ea83-5a2b-a092-f23bea3f03f3', 'b1f06aec-ee7c-5fd7-a1e7-0672ecaac918', '88d7de3e-70c6-53a9-a166-9fd38bd1817b', 5, 5, 'እግዚአብሔር በቀኝኽ ነገሥታትን በቍጣው ቀን ይቀጠቅጣቸዋል'),
  ('2212ddbb-3415-5cab-a5c9-71006339f9b2', 'b1f06aec-ee7c-5fd7-a1e7-0672ecaac918', '88d7de3e-70c6-53a9-a166-9fd38bd1817b', 6, 6, 'በአሕዛብ መካከል ይፈርዳል ሬሳዎችንም ያበዛል በሰፊ ምድር ላይ ራሶችን ይቀጠቅጣል')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('3b33dae8-a635-563d-adce-d8fb3b7abab8', 'b1f06aec-ee7c-5fd7-a1e7-0672ecaac918', '88d7de3e-70c6-53a9-a166-9fd38bd1817b', 7, 7, 'በመንገድ ከፈሳሽ ውሃ ይጠጣል ስለዚህ ራስ ከፍ ከፍ ይላል'),
  ('db3ab06b-e723-57d1-af96-b4ff3fb3db9e', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 1, 1, 'ሃሌ ሉያ አቤቱ በቅኖች ሸንጎ በጉባኤም በፍጹም ልቤ አመሰግንኻለኹ'),
  ('42d78a5f-4736-5551-aee3-1b5ba1d0e7d9', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 2, 2, 'የእግዚአብሔር ሥራ ታላቅ ናት ደስ በሚሠኙባት ዅሉ ዘንድ የተፈለገች ናት'),
  ('b28a356d-4588-51fe-a33d-09978508106a', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 3, 3, 'ሥራው ምስጋናና ግርማ ነው ጽድቁም ለዘለዓለም ይኖራል'),
  ('b9245e00-eb08-5004-aeec-1015b3c3a108', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 4, 4, 'ለተኣምራቱ መታሰቢያን አደረገ እግዚአብሔር መሓሪና ይቅር ባይ ነው'),
  ('a6e5e502-cb32-5b48-a8a8-85b973430b3f', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 5, 5, 'ለሚፈሩት ምግብን ሰጣቸው ኪዳኑንም ለዘለዓለም ያስባል'),
  ('1572a1bd-01c8-569a-aad4-5bf6e221671d', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 6, 6, 'የአሕዛብን ርስት ይሰጣቸው ዘንድ ለሕዝቡ የሥራውን ብርታት አሳየ'),
  ('5ddd8db8-2cda-5fbc-ac53-199e139c1c72', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 7, 7, 'የእጆቹ ሥራ እውነትና ፍርድ ነው ትእዛዙም ዅሉ የታመነ ነው'),
  ('1c63532d-c7c4-5255-a546-c1ba8252ca31', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 8, 8, 'ለዘለዓለምም የጸና ነው በእውነትና በቅንም የተሠራ ነው'),
  ('c3e84419-6000-58a2-a843-08b48e2ef66d', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 9, 9, 'መድኀኒትንም ለሕዝቡ ሰደደ ኪዳኑንም ለዘለዓለም አዘዘ ስሙ የተቀደሰና የተፈራ ነው'),
  ('3323342e-d05e-595e-a74a-2519b5015864', 'dd31c8d0-46de-505e-a067-8b667b621cf6', 'f57b820d-ec65-5aab-a354-d4fc8e19657a', 10, 10, 'የጥበብ መዠመሪያ እግዚአብሔርን መፍራት ነው ለሚያደርጓትም ዅሉ ደኅና ማስተዋል አላቸው ምስጋና ውም ለዘለዓለም ይኖራል'),
  ('acb46ede-51a1-51d7-aff1-ba8dc6c282b0', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 1, 1, 'ሃሌ ሉያ እግዚአብሔርን የሚፈራ ትእዛዙንም እጅግ የሚወድ፟ ሰው ምስጉን ነው'),
  ('252cc7a5-6a49-57f4-adb6-6348b3812b31', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 2, 2, 'ዘሩ በምድር ላይ ኀያል ይኾናል የቅኖች ትውልድ ትባረካለች'),
  ('c87d7f22-4640-5da8-aca3-6db47f7c3ebc', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 3, 3, 'ክብርና ባለጠግነት በቤቱ ነው ጽድቁም ለዘለዓለም ይኖራል'),
  ('cd00874d-53fb-5346-ab85-27b2c1ffeabc', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 4, 4, 'ለቅኖች ብርሃን በጨለማ ወጣ መሓሪና ይቅር ባይ ጻድቅም ነው'),
  ('876d454e-eaa0-5931-a57f-af82bd73b7f0', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 5, 5, 'ቸር ሰው ይራራል ያበድራልም በፍርድም ነገሩን ይፈጽማል'),
  ('f755a162-d6c9-5c28-ae18-a2f413bb4f49', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 6, 6, 'ለዘለዓለም አይናወጥም የጻድቅ መታሰቢያ ለዘለዓለም ይኖራል'),
  ('fd180bac-7378-511d-a4db-c6e3d070c8c7', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 7, 7, 'ከክፉ ነገር አይፈራም በእግዚአብሔር ለመታመን ልቡ የጸና ነው'),
  ('eae242c6-ea84-538a-a504-710c761c3aee', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 8, 8, 'በጠላቶቹ ላይ እስኪያይ ድረስ ልቡ ጽኑ ነው አይፈራም'),
  ('4548ba56-053a-5a60-a90e-d61e830c6a15', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 9, 9, 'በተነ ለችግረኛዎችም ሰጠ ጽድቁ ለዘለዓለም ዓለም ይኖራል ቀንዱ በክብር ከፍ ከፍ ይላል'),
  ('51d09450-c5ef-5dc6-a7a0-4162bde66813', 'e01ccf8a-6e97-5050-afc4-118b5597ef40', 'e87cacd3-5175-599a-a241-50eedeb099eb', 10, 10, 'ኀጢአተኛም አይቶ ይቈጣል ጥርሱንም ያፋጫል ይቀልጣልም የኀጢአተኛዎችም ምኞት ትጠፋለች'),
  ('9bdb74b8-d6f0-56de-a663-a10bb0d24ac2', '97063add-1d44-5f4a-a177-fb2e7ec6b43d', '66ae65f6-7b38-54c8-a104-fa2dce0d4a65', 1, 1, 'ሃሌ ሉያ የእግዚአብሔር ባሪያዎች ሆይ አመስግኑት የእግዚአብሔርንም ስም አመስግኑ'),
  ('f8cc1ead-7e54-5961-a581-7f05f97953f2', '97063add-1d44-5f4a-a177-fb2e7ec6b43d', '66ae65f6-7b38-54c8-a104-fa2dce0d4a65', 2, 2, 'ከዛሬ ዠምሮ እስከ ዘለዓለም ድረስ የእግዚአብሔር ስም ቡሩክ ይኹን'),
  ('4f337adf-b3e5-5304-ab2f-bf511b6df5b8', '97063add-1d44-5f4a-a177-fb2e7ec6b43d', '66ae65f6-7b38-54c8-a104-fa2dce0d4a65', 3, 3, 'ከፀሓይ መውጫ ዠምሮ እስከ መግቢያው ድረስ የእግዚአብሔር ስም ይመስገን'),
  ('3879e3eb-bffe-5474-a147-29d7c2a9c2de', '97063add-1d44-5f4a-a177-fb2e7ec6b43d', '66ae65f6-7b38-54c8-a104-fa2dce0d4a65', 4, 4, 'እግዚአብሔር በአሕዛብ ዅሉ ላይ ከፍተኛ ነው ክብሩም ከሰማያት በላይ ነው'),
  ('451b4ebb-2b78-5890-a4d1-6d4afbeecf23', '97063add-1d44-5f4a-a177-fb2e7ec6b43d', '66ae65f6-7b38-54c8-a104-fa2dce0d4a65', 5, 5, 'እንደ አምላካችን እንደ እግዚአብሔር ማን ነው በላይ የሚኖር'),
  ('350cbfef-212f-51d0-a35c-5e7576b938fb', '97063add-1d44-5f4a-a177-fb2e7ec6b43d', '66ae65f6-7b38-54c8-a104-fa2dce0d4a65', 6, 6, 'በሰማይና በምድር የተዋረዱትን የሚያይ 7-8 ከአለቃዎች ጋራ ከሕዝቡም አለቃዎች ጋራ ያኖረው ዘንድ ችግረኛን ከመሬት የሚያነሣ ምስኪኑንም ከ ፋንድያ ከፍ ከፍ የሚያደርግ'),
  ('bd995941-603e-55f9-a3a5-0d1a15ed4598', '97063add-1d44-5f4a-a177-fb2e7ec6b43d', '66ae65f6-7b38-54c8-a104-fa2dce0d4a65', 7, 9, 'መካኒቱን በቤት የሚያኖራት ደስ የተሠኘችም የልጆች እናት የሚያደርጋት ሃሌ ሉያ'),
  ('a7fc6aec-cdf7-5357-a7a9-643877c44493', '4a8e3f49-ee58-591a-acec-9caeadeb1f05', 'b3b9040a-90cb-5f87-ae60-b12217d42a9a', 1, 1, 'እስራኤል ከግብጽ የያዕቆብም ቤት ከእንግዳ ሕዝብ በወጣ ጊዜ'),
  ('a3b9f51c-c36b-5ca2-a8e9-6eb9373fe97a', '4a8e3f49-ee58-591a-acec-9caeadeb1f05', 'b3b9040a-90cb-5f87-ae60-b12217d42a9a', 2, 2, 'ይሁዳ መቅደሱ እስራኤልም ግዛቱ ኾነ'),
  ('897a688b-59eb-5253-a065-4213816fd52f', '4a8e3f49-ee58-591a-acec-9caeadeb1f05', 'b3b9040a-90cb-5f87-ae60-b12217d42a9a', 3, 3, 'ባሕር አየች ሸሸችም ዮርዳኖስም ወደ ዃላው ተመለሰ'),
  ('60c822b3-cec1-57e7-a431-fef72b5c889a', '4a8e3f49-ee58-591a-acec-9caeadeb1f05', 'b3b9040a-90cb-5f87-ae60-b12217d42a9a', 4, 4, 'ተራራዎች እንደ ኰርማዎች ኰረብታዎችም እንደ ጠቦቶች ዘለሉ'),
  ('68972bcd-1e93-588c-a34e-097677e06f63', '4a8e3f49-ee58-591a-acec-9caeadeb1f05', 'b3b9040a-90cb-5f87-ae60-b12217d42a9a', 5, 5, 'አንቺ ባሕር የሸሸሽ አንቺም ዮርዳኖስ ወደ ዃላሽ የተመለሽ፟ ምን ኾናችዃል'),
