  ('059abc29-7102-5c6b-a4af-e06ff282a65c', '4a8e3f49-ee58-591a-acec-9caeadeb1f05', 'b3b9040a-90cb-5f87-ae60-b12217d42a9a', 7, 7, 'ከያዕቆብ አምላክ ፊት ከጌታ ፊት ምድር ተናወጠች'),
  ('a614f6c5-d947-5391-ad51-74f7ec39788a', '4a8e3f49-ee58-591a-acec-9caeadeb1f05', 'b3b9040a-90cb-5f87-ae60-b12217d42a9a', 8, 8, 'ድንጋዩን ወደውሃ መቆሚያ ጭንጫውንም ወደውሃ ምንጭ ከለወጠ'),
  ('71974d62-8afb-54d3-a5a2-cd44c417c119', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 1, 1, 'ለእኛ አይደለም አቤቱ ለእኛ አይደለም ነገር ግን ለስምኽ ስለ ምሕረትኽ ስለ እውነትኽም ምስጋናን ስጥ'),
  ('f644e0a8-4596-5b25-a5e4-a47924028f75', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 2, 2, 'አሕዛብ፦አምላካቸው ወዴት ነው አይበሉ'),
  ('dbfdaa79-22d1-5b20-ae6e-c9df0449693b', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 3, 3, 'አምላካችንስ በላይ በሰማይ ነው በሰማይም በምድርም የፈቀደውን ዅሉ አደረገ'),
  ('317d6210-7036-59cd-a837-871c7f3e4c3e', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 4, 4, 'የአሕዛብ ጣዖታቶች የወርቅና የብር የሰው እጅ ሥራ ናቸው'),
  ('f6064d44-f0af-58e7-a3c1-fd4d4e57d12e', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 5, 5, 'አፍ አላቸው አይናገሩምም ዐይን አላቸው አያዩምም'),
  ('70e30d65-053d-55e8-ab4e-8d45e3cafba3', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 6, 6, 'ዦሮ አላቸው አይሰሙምም አፍንጫ አላቸው አያሸቱ፟ምም'),
  ('fb099fbd-e78f-5a3f-a1e1-3270ce01ee57', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 7, 7, 'እጅ አላቸው አይዳሰሱምም እግር አላቸው አይኼዱምም በጕረሯቸውም አይናገሩም'),
  ('005ada5c-9ee0-5b07-abbb-c28ae26e4ae1', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 8, 8, 'የሚሠሯቸውም የሚያምኑባቸውም ዅሉ እንደ እነርሱ ይኹኑ'),
  ('ec125ff0-cb44-5820-aaa4-c253d9d92e5c', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 9, 9, 'የእስራኤል ቤት ሆይ በእግዚአብሔር ታመኑ ረድኤታቸውና መታመኛቸው ርሱ ነው'),
  ('4449807b-aad6-5c55-a7c7-132efbecc2ff', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 10, 10, 'የአሮን ቤት ሆይ በእግዚአብሔር ታመኑ ረድኤታቸውና መታመኛቸው ርሱ ነው'),
  ('e8b23750-cecb-547e-a927-05977fd8473d', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 11, 11, 'እግዚአብሔርን የምትፈሩ ሆይ በእግዚአብሔር ታመኑ ረድኤታቸውና መታመኛቸው ርሱ ነው'),
  ('72d6289c-4560-5add-a16e-289afff3c8ab', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 12, 12, 'እግዚአብሔር ዐሰበን ይባርከንማል የእስራኤልን ቤት ይባረካል የአሮንንም ቤት ይባረካል'),
  ('43a3780a-e4e5-54ee-a4c7-1ad694de1002', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 13, 13, 'እግዚአብሔርን የሚፈሩትን ትንንሾችንና ትልልቆችን ይባርካል'),
  ('3dca3da5-7222-58f1-afb1-5f81203b4ea1', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 14, 14, 'እግዚአብሔር በላያችኹ በላያችኹና በልጆቻችኹ ላይ ይጨምር'),
  ('a4e29f93-bbed-5996-acd5-e07c085a14ea', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 15, 15, 'እናንተ ሰማይንና ምድርን ለሠራ ለእግዚአብሔር የተባረካችኹ ናችኹ'),
