  ('aff5c4f0-69c9-5dc8-a6eb-ba0b2998a4f4', '21132ec7-e1f5-58ff-a21b-1503290ce637', '264ce16b-59e3-500f-a653-a093e226d20e', 18, 18, 'እኛ ሕያዋን ግን ከዛሬ ዠምሮ እስከ ዘለዓለም እግዚአብሔርን እንባርካለን ሃሌ ሉያ'),
  ('1e481c10-3855-5b6e-a79c-ed25120981fd', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 1, 1, 'እግዚአብሔር የልመናዬን ድምፅ ሰምቷልና ወደድኹት'),
