  ('4500f914-f70d-5e98-aea9-393752ee3496', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 4, 4, 'የእግዚአብሔርንም ስም ጠራኹ፦አቤቱ ነፍሴን አድናት'),
  ('671f6a38-2cbf-54cb-a5f3-490452c01f11', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 5, 5, 'እግዚአብሔር መሓሪና ጻድቅ ነው አምላካችንም ይቅር ባይ ነው'),
  ('9d62c79e-fc79-5787-a335-15494845b012', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 6, 6, 'እግዚአብሔር ሕፃናትን ይጠብቃል ተቸገርኹ ርሱም አዳነኝ'),
  ('e45f59a9-ecb2-5384-a418-4e9f2b931bd8', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 7, 7, 'ነፍሴ ሆይ ወደ ዕረፍትሽ ተመለሺ እግዚአብሔር መልካም አድርጎልሻልና'),
  ('c6b3938c-70d7-5b8a-abac-be8cbaa91753', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 8, 8, 'ነፍሴን ከሞት ዐይኔንም ከእንባ እግሬንም ከመሰናከል አድኗልና'),
  ('2c273f3c-8e97-5d8d-a303-551ecc0548e2', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 9, 9, 'በሕያዋን አገር በእግዚአብሔር ፊት እኼዳለኹ'),
  ('477bf69a-bc34-5205-ae8c-352957715c38', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 10, 10, 'አመንኹ ስለዚህም ተናገርኹ እኔም እጅግ ተቸገርኹ'),
  ('0a18ec54-12e8-597b-a9da-074e3f70d8b0', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 11, 11, 'እኔም ከድንጋጤዬ የተነሣ፦ሰው ዅሉ ሐሰተኛ ነው አልኹ'),
  ('ac55d04b-9c7c-5833-a58c-b8090bc9da04', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 12, 12, 'ስላደረገልኝ ዅሉ ለእግዚአብሔር ምንን እመልሳለኹ'),
  ('4529a18c-3dbe-5074-abd8-717e384bce0e', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 13, 13, 'የመድኀኒትን ጽዋ እቀበላለኹ የእግዚአብሔርንም ስም እጠራለኹ'),
  ('b70c238d-b282-5cef-a23a-1233ed8bf6fd', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 14, 14, 'በሕዝቡ ዅሉ ፊት ስእለቴን ለእግዚአብሔር እፈጽማለኹ'),
  ('b94ec3fb-5a9d-58b1-a082-1ead47110dfd', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 15, 15, 'የቅዱሳኑ ሞት በእግዚአብሔር ፊት የከበረ ነው'),
  ('d3e19223-af44-55d5-a809-897aab4530d5', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 16, 16, 'አቤቱ እኔ ባሪያኽ ነኝ ባሪያኽ ነኝ የሴት ባሪያኽም ልጅ ነኝ ሰንሰለቴን ሰበርኽ'),
  ('f614a24a-b1d7-5983-a60c-d04e9eb0a2db', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 17, 17, 'ለአንተ የምስጋና መሥዋዕትን እሠዋለኹ የእግዚአብሔርንም ስም እጠራለኹ'),
  ('535102e9-52a4-50d5-af63-5630d4b9b5eb', '03b799cc-ada9-5e4d-a2b5-9dbeaaebddaf', '2b61ad89-9f49-510c-a6a1-17be55ca1eee', 18, 18, 'በሕዝቡ ዅሉ ፊት ስእለቴን ለእግዚአብሔር እፈጽማለኹ'),
